/* Gerado por npm run styles:build. Editar ui-styles/*.css. */
@font-face{font-family:'DM Sans';src:url('assets/fonts/dm-sans.ttf') format('truetype');font-style:normal;font-weight:100 1000;font-display:swap;}
.header-actions{display:flex;align-items:center;gap:10px}
.month-close{margin-top:20px}
.checklist{display:grid;gap:8px;margin-top:16px}
.check-item{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:13px}
.check-item small{color:var(--muted)}
.check-status{color:var(--green);font-weight:700;font-size:12px}
.check-status.pending{color:var(--orange)}
textarea{width:100%;border:1px solid #dfe4eb;border-radius:7px;padding:10px 11px;font:14px 'DM Sans';color:var(--ink);background:#fff;resize:vertical}
.tag{display:inline-block;background:#f0f3f7;color:var(--muted);font-size:10px;border-radius:9px;padding:2px 6px;margin:4px 3px 0 0}
.cash-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:20px}
.cash-agenda-row{display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}
.cash-date{width:43px;height:43px;border-radius:9px;background:var(--blue-pale);display:grid;place-items:center;color:var(--blue);font-weight:700;font-size:12px}
.action-stack{display:grid;gap:10px;margin:18px 0}
.secondary{border:1px solid #cbd6ed;border-radius:9px;padding:11px;background:#fff;color:var(--blue);font:600 13px 'DM Sans';cursor:pointer}
.reconcile-row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line);font-size:12px}
.simulator{margin-top:20px}
.simulator-fields{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin:20px 0}
.simulator-fields label{font-size:12px;font-weight:600;display:grid;gap:7px}
.simulation-result{margin-top:20px;padding:17px;background:var(--blue-pale);border-radius:9px;font-size:14px}
.simulation-result strong{font-size:23px;display:block;margin-top:4px}
.receipt-button{border:0;background:var(--blue-pale);color:var(--blue);border-radius:5px;padding:4px 6px;font-size:11px;cursor:pointer}
@media(max-width:800px){.cash-cards,.simulator-fields{grid-template-columns:1fr}}
.debt-summary,.report-cards,.wealth-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:20px}
.summary-card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:18px}
.summary-card p{font-size:12px;margin-bottom:8px}
.summary-card strong{font-size:24px}
.debt-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:17px}
.debt-card{background:#fff;border:1px solid var(--line);border-radius:13px;padding:21px;border-top:4px solid var(--red)}
.debt-card.card-credit{border-top-color:var(--orange)}
.debt-card h3{margin:0;font-size:16px}
.debt-card p{font-size:12px;margin:6px 0 18px}
.debt-stat{font-size:26px;font-weight:700;margin-bottom:12px}
.debt-details{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:16px 0}
.debt-details div{background:var(--canvas);border-radius:7px;padding:9px;font-size:11px;color:var(--muted)}
.debt-details b{display:block;color:var(--ink);font-size:13px;margin-top:3px}
.annual-panel{margin-bottom:20px}
.annual-chart{height:260px;display:flex;align-items:end;gap:10px;padding:20px 5px 0;border-bottom:1px solid var(--line)}
.annual-group{height:100%;flex:1;display:flex;gap:3px;align-items:end;justify-content:center;position:relative;padding-bottom:20px}
.annual-group .bar{width:12px}
.annual-label{position:absolute;bottom:0;font-size:10px;color:var(--muted)}
.report-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.alerts-list{margin-top:17px}
.alert{border-left:3px solid var(--orange);padding:10px 12px;background:#fff9ed;margin:10px 0;border-radius:0 7px 7px 0;font-size:12px}
.alert.danger{border-color:var(--red);background:#fff3f2}
.alert.good{border-color:var(--green);background:#f0faf6}
.investment-row{display:flex;justify-content:space-between;align-items:center;padding:14px 0;border-bottom:1px solid var(--line)}
.investment-row b{font-size:13px}
.investment-meta{font-size:11px;color:var(--muted);margin-top:3px}
.report-select{width:auto}
@media(max-width:800px){.debt-summary,.report-cards,.wealth-cards{grid-template-columns:1fr 1fr}}
@media(max-width:800px){.report-grid{grid-template-columns:1fr}}
@media(max-width:500px){.debt-summary,.report-cards,.wealth-cards{grid-template-columns:1fr}}
.review-layout{display:grid;grid-template-columns:1.35fr .65fr;gap:20px}
.review-message{font-size:13px;color:var(--muted);padding:0 0 15px}
.review-table-row{display:grid;grid-template-columns:1.1fr 1.5fr 1fr 1fr .9fr;gap:9px;align-items:center;padding:10px 3px;border-bottom:1px solid var(--line);font-size:12px}
.review-table-row input{padding:7px;font-size:12px}
.review-actions{display:flex;justify-content:space-between;align-items:center;padding-top:18px}
.rules-panel{height:max-content}
.rule-row{padding:12px 0;border-bottom:1px solid var(--line);font-size:12px}
.rule-row b{display:block;margin-bottom:3px}
.rule-row span{color:var(--muted)}
.pin-lock{position:fixed;inset:0;z-index:20;background:#14213df4;display:grid;place-items:center;padding:20px}
.pin-card{width:min(360px,100%);background:#fff;border-radius:17px;padding:34px;text-align:center}
.pin-card h2{font:600 25px Fraunces,serif;margin:15px 0 8px}
.pin-card p{margin-bottom:18px}
.pin-card input{text-align:center;letter-spacing:.35em;font-size:20px}
.pin-icon{width:42px;height:42px;display:inline-grid;place-items:center;border-radius:11px;background:var(--blue);color:#fff;font-size:24px}
.pin-card small{display:block;color:var(--red);min-height:16px;margin-top:9px}
@media(max-width:700px){.review-layout{grid-template-columns:1fr}}
@media(max-width:700px){.review-table-row{grid-template-columns:1.2fr 1fr .8fr}}
@media(max-width:700px){.review-table-row>:nth-child(4),.review-table-row>:nth-child(5){display:none}}
.month-picker{width:auto;min-width:178px;border:0;background:transparent;padding:2px 25px 2px 0;font:600 19px 'DM Sans';color:var(--ink)}
.contribute{border:0;background:var(--blue-pale);color:var(--blue);font:600 12px 'DM Sans';padding:7px 9px;border-radius:7px;cursor:pointer}
.planner-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:20px}
.calendar-list{margin-top:14px}
.calendar-day{display:grid;grid-template-columns:47px 1fr auto;gap:13px;align-items:center;padding:13px 0;border-bottom:1px solid var(--line)}
.calendar-date{width:43px;height:43px;border-radius:10px;background:var(--blue-pale);color:var(--blue);display:grid;place-items:center;font-weight:700;font-size:14px}
.calendar-title{font-weight:600;font-size:13px}
.calendar-meta{font-size:11px;color:var(--muted);margin-top:3px}
.forecast{background:linear-gradient(145deg,#edf2ff,#fff);min-height:275px}
.forecast .insight-label{margin-bottom:22px;text-transform:uppercase;letter-spacing:.08em;font-size:11px;font-weight:700;color:var(--blue)}
.forecast strong{font:600 36px Fraunces,serif;letter-spacing:-.04em}
.forecast-rule{height:1px;background:#cdd8f1;margin:22px 0 12px}
.forecast-item{display:flex;justify-content:space-between;padding:8px 0;font-size:12px}
@media(max-width:700px){.planner-grid{grid-template-columns:1fr}}
.insights-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.insight-hero{background:linear-gradient(135deg,#14213d,#293c64);border:0;color:#fff;min-height:210px}
.insight-hero p{color:#c6d1e7}
.insight-hero .insight-label{text-transform:uppercase;letter-spacing:.08em;font-size:11px;font-weight:700;color:#9fb5de}
.insight-hero h2{font:600 27px Fraunces,serif;margin:22px 0 4px}
.insight-hero strong{font-size:27px}
.breakdown{margin-top:18px}
.breakdown-row{display:grid;grid-template-columns:105px 1fr 62px;gap:10px;align-items:center;margin:12px 0;font-size:12px}
.breakdown-row b{font-size:12px;text-align:right}
.recurring-panel{min-height:210px}
.recurring-badge{font-size:10px;color:var(--blue);background:var(--blue-pale);border-radius:10px;padding:4px 7px;margin-left:5px}
.summary-list{margin-top:20px}
.summary-row{padding:11px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;font-size:13px}
.summary-row span{color:var(--muted)}
.checkbox{display:flex!important;align-items:center;gap:9px}
.checkbox input{width:auto}
@media(max-width:700px){.insights-grid{grid-template-columns:1fr}}
@media(max-width:700px){.breakdown-row{grid-template-columns:82px 1fr 56px}}
:root{--ink:#172033;--muted:#697385;--line:#e8ebf0;--paper:#fff;--canvas:#f7f8fa;--navy:#14213d;--blue:#3767e8;--blue-pale:#edf2ff;--green:#1c9b70;--red:#e65855;--orange:#f2a33b}
*{box-sizing:border-box}
body{margin:0;background:var(--canvas);font-family:'DM Sans',sans-serif;color:var(--ink)}
.sidebar{position:fixed;inset:0 auto 0 0;width:244px;padding:30px 18px;background:var(--navy);color:#dce4f5;display:flex;flex-direction:column}
.brand{color:#fff;text-decoration:none;font-size:22px;font-family:Fraunces,serif;margin:0 12px 40px}
.brand span{display:inline-grid;place-items:center;border-radius:10px;background:#4e7df2;width:30px;height:30px;font-family:'DM Sans';font-size:19px;margin-right:8px}
nav{display:grid;gap:7px}
.nav-link,.text-button{border:0;background:transparent;color:#aeb9d0;text-align:left;font:inherit;cursor:pointer;border-radius:8px;padding:12px 13px;font-size:15px}
.nav-link:hover,.nav-link.active{background:#263653;color:#fff}
.nav-link{display:flex;gap:13px;align-items:center}
.sidebar-bottom{margin-top:auto;display:grid;gap:4px}
.text-button{font-size:13px}
.danger{color:#e5a2a2}
main{margin-left:244px;padding:38px max(42px,5vw) 60px;max-width:1600px}
header,.section-head,.panel-heading,.period-row{display:flex;align-items:center;justify-content:space-between;gap:18px}
header{margin-bottom:32px}
.eyebrow{text-transform:uppercase;letter-spacing:.1em;font-size:11px;font-weight:700;color:var(--muted);margin:0 0 7px}
h1,h2,p{margin-top:0}
h1{font:600 32px Fraunces,serif;margin-bottom:0}
h2{font-size:17px;margin-bottom:5px}
p{color:var(--muted);font-size:14px}
.primary{border:0;border-radius:9px;padding:12px 16px;color:#fff;background:var(--blue);font:600 14px 'DM Sans';cursor:pointer;box-shadow:0 5px 13px #3767e833}
.primary:hover{background:#2556dc}
.period-row{margin-bottom:16px}
.period-row h2{font-size:19px;margin:0}
.pill{background:var(--blue-pale);color:var(--blue);font-size:12px;font-weight:600;padding:6px 10px;border-radius:20px}
.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:20px}
.metric,.panel{background:var(--paper);border:1px solid var(--line);border-radius:13px}
.metric{padding:21px}
.metric p{margin-bottom:11px}
.metric strong{display:block;font-size:25px;letter-spacing:-.04em;margin-bottom:8px}
.metric small{font-size:12px;color:var(--muted)}
.metric.balance{background:var(--navy);border-color:var(--navy)}
.metric.balance p,.metric.balance small{color:#b8c6dc}
.metric.balance strong{color:#fff}
.positive{color:var(--green)!important}
.negative{color:var(--red)!important}
.dashboard-grid{display:grid;grid-template-columns:1.35fr .85fr;gap:20px}
.panel{padding:21px}
.panel-heading p{margin-bottom:0;font-size:12px}
.link-button{border:0;background:transparent;color:var(--blue);font:600 13px 'DM Sans';cursor:pointer}
.chart-panel{min-height:285px}
.legend{font-size:11px;color:var(--muted);display:flex;gap:5px;align-items:center}
.legend i{width:7px;height:7px;background:var(--blue);display:inline-block;border-radius:50%}
.legend .expense-dot{background:#f4b14c;margin-left:6px}
.chart{height:194px;display:flex;gap:15px;align-items:end;border-bottom:1px solid var(--line);padding:12px 8px 0;margin-top:10px}
.bar-group{height:100%;flex:1;display:flex;align-items:end;justify-content:center;gap:4px;position:relative;padding-bottom:20px}
.bar{width:12px;max-width:38%;border-radius:5px 5px 1px 1px;background:var(--blue)}
.bar.out{background:#f4b14c}
.bar-label{position:absolute;bottom:0;font-size:10px;color:var(--muted)}
.budget-summary,.goals-card{min-height:0}
.budget-row{margin-top:17px}
.row-top,.transaction-item,.account-head{display:flex;justify-content:space-between;align-items:center;gap:10px}
.row-top{font-size:13px;margin-bottom:7px}
.row-top span:last-child{color:var(--muted);font-size:11px}
.progress{background:#edf0f4;height:7px;border-radius:10px;overflow:hidden}
.progress>i{display:block;height:100%;background:var(--blue);border-radius:10px}
.progress i.warn{background:var(--orange)}
.recent,.goals-card{min-height:257px}
.transaction-item{padding:13px 0;border-bottom:1px solid var(--line)}
.transaction-item:last-child{border:0}
.transaction-name{font-weight:600;font-size:13px}
.transaction-meta{font-size:11px;color:var(--muted);margin-top:3px}
.amount{font-size:13px;font-weight:700}
.amount.expense{color:var(--red)}
.amount.income{color:var(--green)}
.goal-row{margin-top:19px}
.goal-row .row-top{margin-bottom:8px}
.goal-row b{font-size:13px}
.goal-row small{font-size:11px;color:var(--muted)}
.view{display:none}
.view.active{display:block}
.section-head{margin-bottom:24px}
.section-head h2{font:600 28px Fraunces,serif;margin-bottom:7px}
.section-head p{margin-bottom:0}
.filters{display:flex;gap:10px;border-bottom:1px solid var(--line);padding-bottom:16px;margin-bottom:4px}
input,select{width:100%;border:1px solid #dfe4eb;border-radius:7px;padding:10px 11px;font:14px 'DM Sans';color:var(--ink);background:#fff}
select{max-width:180px}
.table-row{display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;align-items:center;padding:15px 5px;border-bottom:1px solid var(--line);font-size:13px}
.table-head{color:var(--muted);font-size:11px;text-transform:uppercase;font-weight:700}
.delete{border:0;background:transparent;color:#a0a9b6;cursor:pointer;font-size:18px}
.budget-grid,.goals-grid,.accounts-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:17px}
.budget-card,.goal-card,.account-card{background:#fff;border:1px solid var(--line);border-radius:13px;padding:22px}
.budget-card h3,.goal-card h3,.account-card h3{margin:0;font-size:16px}
.budget-card p,.goal-card p{font-size:12px;margin:7px 0 16px}
.budget-amount{font-size:24px;font-weight:700;margin-bottom:12px}
.goal-card{min-height:190px}
.goal-icon{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:var(--blue-pale);font-size:19px;margin-bottom:18px}
.goal-card .progress{margin:15px 0 9px}
.account-card{border-top:4px solid var(--blue)}
.account-card:nth-child(2){border-top-color:var(--green)}
.account-card:nth-child(3){border-top-color:var(--orange)}
.account-card strong{font-size:25px;display:block;margin:16px 0 4px}
.account-card small{color:var(--muted)}
dialog{border:0;border-radius:16px;padding:0;width:min(460px,calc(100% - 32px));box-shadow:0 20px 60px #14213d55}
dialog::backdrop{background:#14213d88}
dialog form{padding:28px;position:relative}
dialog h2{font:600 24px Fraunces,serif;margin-bottom:5px}
.modal-subtitle{margin-bottom:22px}
dialog label{display:grid;gap:7px;font-size:12px;font-weight:600;margin:13px 0}
.two-cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.full{width:100%;margin-top:12px}
.close{position:absolute;right:16px;top:13px;border:0;background:transparent;font-size:25px;color:var(--muted);cursor:pointer}
.type-tabs{display:flex;gap:10px;background:var(--canvas);border-radius:8px;padding:2px}
.type-tabs label{display:block;flex:1;padding:9px;margin:0;text-align:center;font-size:13px}
.type-tabs input{width:auto}
.empty{color:var(--muted);font-size:14px;padding:25px 0;text-align:center}
@media(max-width:980px){.cards{grid-template-columns:repeat(2,1fr)}}
@media(max-width:980px){.dashboard-grid{grid-template-columns:1fr}}
@media(max-width:980px){.sidebar{width:68px;padding:25px 9px}}
@media(max-width:980px){.brand{font-size:0;margin:0 10px 36px}}
@media(max-width:980px){.brand span{margin:0}}
@media(max-width:980px){.nav-link{justify-content:center;padding:12px}}
@media(max-width:980px){.nav-link span,.sidebar-bottom{display:none}}
@media(max-width:980px){main{margin-left:68px}}
@media(max-width:620px){main{padding:25px 18px 45px;margin-left:0;padding-bottom:80px}}
@media(max-width:620px){.sidebar{top:auto;width:100%;height:62px;z-index:4;display:block;padding:5px 10px}}
@media(max-width:620px){.brand{display:none}}
@media(max-width:620px){nav{display:flex;grid-template-columns:repeat(5,1fr);gap:2px}}
@media(max-width:620px){.nav-link{font-size:19px;padding:9px 4px}}
@media(max-width:620px){.cards{grid-template-columns:1fr 1fr;gap:10px}}
@media(max-width:620px){.metric{padding:15px}}
@media(max-width:620px){.metric strong{font-size:20px}}
@media(max-width:620px){header h1{font-size:26px}}
@media(max-width:620px){header .primary{font-size:12px;padding:10px}}
@media(max-width:620px){.section-head h2{font-size:24px}}
@media(max-width:620px){.table-row{grid-template-columns:1.6fr 1fr auto}}
@media(max-width:620px){.table-row>:nth-child(3),.table-row>:nth-child(4),.table-head>:nth-child(3),.table-head>:nth-child(4){display:none}}
@media(max-width:620px){.filters{display:grid}}
@media(max-width:620px){.filters select{max-width:none}}
.import-dialog {
  width: min(820px, calc(100% - 24px));
}
.mapping-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 18px;
  margin: 20px 0;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}
.mapping-grid label {
  min-width: 0;
}
.mapping-grid select {
  width: 100%;
  text-overflow: ellipsis;
}
.import-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 8px;
  background: var(--blue-pale);
  font-size: 14px;
}
.import-errors {
  background: #fff5f3;
  border: 1px solid #efd1cb;
  border-radius: 8px;
  padding: 14px;
  margin-top: 18px;
  font-size: 14px;
}
.import-errors summary {
  font-weight: 600;
  cursor: pointer;
}
.import-errors ol {
  padding-left: 20px;
  max-height: 220px;
  overflow: auto;
}
.import-errors li {
  margin: 12px 0;
}
.import-errors small {
  display: block;
  overflow-wrap: anywhere;
}
.import-footnote {
  margin-top: 18px;
}
#importPreview h3 {
  font-size: 16px;
  margin: 22px 0 8px;
}
@media (max-width: 550px) {
  .mapping-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 550px) {
  .import-stats {
    gap: 7px;
    flex-direction: column;
  }
}
@media (max-width: 550px) {
  .import-dialog form {
    padding: 22px 18px;
  }
}
:root {
  --blue: #285de0;
  --ink: #17243a;
  --muted: #58667b;
  --canvas: #f3f6fb;
  --line: #dfe6f0;
}
body {
  font-size: 16px;
  line-height: 1.5;
}
button,
input,
select,
textarea {
  font: inherit;
}
button {
  transition:
    background 0.15s,
    box-shadow 0.15s;
}
button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid #6395ff;
  outline-offset: 3px;
}
p {
  font-size: 14px;
  line-height: 1.65;
}
small {
  font-size: 12px;
  color: var(--muted);
}
h2 {
  font-size: 18px;
}
input,
select,
textarea {
  min-height: 44px;
  font-size: 15px;
}
select {
  max-width: none;
}
.primary,
.secondary {
  font-size: 14px;
  min-height: 42px;
}
.link-button {
  font-size: 14px;
  min-height: 36px;
}
.danger {
  color: #ad3333;
}
.sidebar .danger {
  color: #ffb6b6;
}
.sidebar {
  width: 238px;
  padding: 25px 16px 16px;
  overflow-y: auto;
  z-index: 15;
}
.brand {
  margin-bottom: 28px;
  font-size: 25px;
}
.brand span {
  background: #4579ef;
  width: 35px;
  height: 35px;
}
.sidebar nav {
  gap: 3px;
}
.nav-link {
  min-height: 42px;
  padding: 8px 13px;
  font-size: 14px;
  flex-shrink: 0;
}
.nav-link.active {
  background: #315181;
  box-shadow: inset 3px 0 #89aaff;
}
.sidebar-bottom {
  margin-top: 24px;
  border-top: 1px solid #ffffff20;
  padding-top: 12px;
  gap: 0;
}
.sidebar-bottom .text-button {
  padding: 7px 12px;
  min-height: 35px;
}
.sidebar-bottom #resetData {
  display: none;
}
main {
  margin-left: 238px;
  max-width: 1700px;
  padding: 32px clamp(24px, 4vw, 64px) 70px;
}
header {
  margin-bottom: 20px;
}
header h1 {
  font-size: 34px;
}
.workspace-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
}
.period-row {
  margin: 0;
  gap: 12px;
  justify-content: flex-start;
}
.month-picker {
