}
.pill {
  white-space: nowrap;
}
.demo-banner {
  display: flex;
  gap: 20px;
  align-items: center;
  justify-content: space-between;
  background: #e5edff;
  border: 1px solid #c9d9fb;
  padding: 16px 20px;
  border-radius: 12px;
  margin-bottom: 24px;
}
.demo-banner span {
  display: block;
  font-size: 13px;
  color: #3c5279;
  margin-top: 3px;
}
.demo-banner button {
  white-space: nowrap;
  background: #fff;
}
.metric {
  padding: 22px;
  border-radius: 13px;
}
.metric strong {
  font-size: 28px;
  letter-spacing: -0.025em;
}
.metric p {
  font-size: 14px;
}
.metric small {
  font-size: 12px;
}
.cards {
  gap: 15px;
  margin-bottom: 24px;
}
.panel {
  padding: 24px;
  box-shadow: 0 3px 16px #19345604;
}
.dashboard-grid {
  grid-template-columns: minmax(0, 1.25fr) minmax(290px, 0.85fr);
  gap: 24px;
}
.panel-heading {
  align-items: flex-start;
}
.panel-heading h2 {
  margin-bottom: 3px;
}
.chart {
  height: 220px;
  gap: 12px;
}
.bar {
  width: 19px;
  border-radius: 5px 5px 0 0;
}
.bar-label {
  font-size: 12px;
}
.legend {
  font-size: 12px;
  flex-wrap: wrap;
}
.budget-row small {
  display: block;
  margin-top: 7px;
}
.row-top {
  font-size: 14px;
  align-items: flex-start;
}
.row-top span:last-child {
  font-size: 12px;
}
.progress {
  height: 8px;
  margin-top: 9px;
}
.transaction-item {
  gap: 15px;
  padding: 17px 0;
  align-items: center;
}
.transaction-item > div:first-child {
  min-width: 0;
  overflow-wrap: anywhere;
}
.transaction-item b {
  font-size: 14px;
}
.transaction-meta {
  font-size: 12px;
  margin-top: 4px;
}
.transaction-right {
