  text-align: right;
  max-width: 47%;
}
.amount {
  font-size: 15px;
  white-space: nowrap;
}
.row-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 13px;
}
.transaction-right .row-actions {
  justify-content: flex-end;
  gap: 4px;
  margin-top: 4px;
}
.row-actions .link-button {
  padding: 2px 5px;
}
.goal-card p {
  margin-top: 16px;
}
.goal-icon {
  margin-bottom: 12px;
}
.goal-row {
  margin-top: 12px;
}
.goal-row b {
  font-size: 14px;
}
.goal-row .row-top {
