  color: #9aadc7;
}
.empty-state p {
  margin: 10px 0 0;
}
.summary-card small {
  display: block;
  margin-top: 8px;
}
.summary-card p {
  font-size: 14px;
}
.summary-card strong {
  font-size: 26px;
}
.budget-card,
.goal-card,
