}
.report-grid .panel h2 {
  margin-bottom: 10px;
}
.report-cards,
.wealth-cards,
.debt-summary,
.cash-cards {
  gap: 18px;
}
.breakdown-row {
  grid-template-columns: minmax(90px, 1fr) minmax(60px, 1fr) auto;
  font-size: 14px;
  gap: 12px;
  margin: 18px 0;
}
.breakdown-row b {
  font-size: 13px;
}
.alert {
  font-size: 14px;
  padding: 14px;
}
.check-item {
  font-size: 14px;
}
.investment-row p {
  font-size: 12px;
  margin: 4px 0;
}
.review-layout {
  grid-template-columns: minmax(0, 1.6fr) minmax(240px, 0.7fr);
}
.import-row {
  display: grid;
  grid-template-columns: 22px minmax(100px, 1fr) minmax(110px, 0.7fr) auto;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--line);
  padding: 16px 0;
}
