}
.import-row b {
  font-size: 14px;
}
.import-row small {
  display: block;
}
.import-row input {
  font-size: 14px;
  min-width: 0;
}
.review-message {
  font-size: 14px;
}
.review-actions {
  gap: 12px;
}
.rule-row {
  font-size: 14px;
}
.settings-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.settings-label {
  display: block;
  font-size: 14px;
  margin: 18px 0 8px;
}
.help-list {
  padding-left: 20px;
  font-size: 14px;
  color: var(--muted);
}
.help-list li {
  margin: 12px 0;
}
.settings-grid .panel {
  align-self: start;
}
.simulator-fields label {
  font-size: 14px;
}
.simulation-result {
  font-size: 16px;
  padding: 22px;
}
.simulation-result small {
  display: block;
  margin-top: 12px;
}
.forecast strong {
  font-size: 35px;
}
.notice {
  position: fixed;
  bottom: 22px;
  left: calc(50% + 100px);
  transform: translateX(-50%);
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 20px;
  max-width: min(700px, 85vw);
  background: #173951;
  color: white;
  border: 1px solid #ffffff30;
  padding: 15px 20px;
  border-radius: 11px;
  box-shadow: 0 8px 30px #17243a33;
  font-size: 14px;
}
.notice.error {
  background: #872d35;
}
.notice button {
  background: transparent;
  border: 0;
  color: inherit;
  text-decoration: underline;
  cursor: pointer;
  padding: 8px;
}
.notice[hidden],
[hidden] {
  display: none !important;
}
dialog {
  width: min(520px, calc(100% - 30px));
  max-height: 90dvh;
  overflow: auto;
}
dialog label {
  font-size: 14px;
  margin: 16px 0;
}
dialog h2 {
  padding-right: 25px;
}
dialog .modal-subtitle {
  font-size: 14px;
  margin-top: 10px;
}
.close {
  cursor: pointer;
  min-height: 36px;
  min-width: 36px;
}
#formError {
  background: #fff0f0;
  color: #9a2834;
  padding: 12px;
  border-radius: 8px;
  font-size: 14px;
}
#menuToggle,
#menuBackdrop {
  display: none;
}
.skip-link {
  position: fixed;
  top: -60px;
  left: 15px;
  z-index: 200;
  background: white;
  padding: 12px;
  color: var(--blue);
}
.skip-link:focus {
