.dashboard-accounts {
  margin: -6px 0 24px;
}
.dashboard-accounts-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  margin-bottom: 10px;
}
.dashboard-accounts-heading h2,
.dashboard-accounts-heading p { margin: 0; }
.dashboard-accounts-heading p { color: var(--muted); margin-top: 2px; }
.dashboard-account-balances {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 10px;
}
.dashboard-account-balance {
  min-height: 68px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface, #fff);
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.dashboard-account-balance span {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.3;
}
.dashboard-account-balance strong {
  margin-top: 3px;
  font-size: 18px;
  line-height: 1.25;
}
.space-picker select,
.space-picker button,
.space-actions button { min-height: 40px; }
.space-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.period-row, .header-actions, .panel-heading, .row-actions { align-items: center; }
.report-select, .month-picker { min-height: 42px; }
:root {
  --ink: #182824;
  --muted: #63716d;
  --line: #e3e9e6;
  --paper: #fff;
  --canvas: #f5f7f6;
  --navy: #14382f;
  --blue: #147c5a;
  --blue-pale: #e8f3ed;
  --green: #147c5a;
  --red: #b4414e;
  --orange: #b77b2f;
  --font: "Segoe UI Variable", "Segoe UI", system-ui, sans-serif;
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: var(--font);
  background: var(--canvas);
  font-size: 15px;
  line-height: 1.55;
  color: var(--ink);
}
button,
input,
select,
textarea {
  font-family: var(--font) !important;
}
h1,
h2,
h3,
.brand,
.forecast strong,
.section-head h2,
dialog h2 {
  font-family: var(--font);
  letter-spacing: -0.025em;
}
button {
  box-shadow: none !important;
}
button,
input,
select,
textarea {
  border-radius: 9px;
}
.primary {
  background: var(--blue);
  font-weight: 600;
  padding: 11px 17px;
  min-height: 42px;
}
.primary:hover {
  background: #0f6147;
}
.secondary {
  background: #fff;
  border-color: #d5dfda;
  color: #294c3c;
  font-weight: 600;
  padding: 9px 14px;
}
.secondary:hover {
  background: #edf5ef;
}
.link-button {
  color: #21664a;
  font-weight: 600;
  font-size: 13px;
}
.danger {
  color: var(--red);
}
.positive {
  color: var(--green) !important;
}
.negative {
  color: var(--red) !important;
}
p {
  line-height: 1.6;
}
.sidebar {
  width: 224px;
  background: #13382f;
  padding: 27px 17px 16px;
  display: flex;
  flex-direction: column;
  overflow: auto;
  color: #e2eee7;
  scrollbar-width: thin;
  scrollbar-color: #375b50 transparent;
}
.brand {
  font-size: 23px;
  font-weight: 650;
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 8px 24px;
  color: #f1f6f2;
  letter-spacing: -0.04em;
}
.brand span {
  display: grid;
  place-items: center;
  background: #d8ecbc;
  color: #173c2e;
  width: 31px;
  height: 31px;
  border-radius: 9px;
  font-size: 21px;
  margin: 0;
}
.sidebar nav {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.nav-group {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #88a89a;
  margin: 16px 11px 6px;
  font-weight: 650;
}
.nav-link {
  font-size: 13px;
  line-height: 1.4;
  padding: 9px 11px;
  min-height: 37px;
  gap: 11px;
  color: #aec6b9;
  border-radius: 7px;
  text-align: left;
  justify-content: flex-start;
}
.nav-link svg {
  height: 17px;
  width: 17px;
  flex: none;
  opacity: 0.8;
}
.nav-link span {
  display: inline;
}
.nav-link:hover {
  background: #21493b;
  color: #fff;
}
.nav-link.active {
  background: #d7eac5;
  color: #173b2b;
  font-weight: 650;
  box-shadow: none;
}
.nav-link.active svg {
  opacity: 1;
}
.sidebar-bottom {
  padding-top: 16px;
  margin-top: 25px;
  border-top: 1px solid #ffffff14;
  gap: 1px;
}
.sidebar-bottom .text-button {
  font-size: 12px;
  min-height: 32px;
  padding: 6px 11px;
  color: #b4c9bc;
}
.sidebar-bottom #importCsv {
  display: none;
}
.sidebar-bottom .text-button:hover {
  background: #234a3d;
  color: #fff;
}
main {
  margin-left: 224px;
  max-width: 1730px;
  padding: 32px clamp(24px, 3.5vw, 58px) 60px;
}
header {
  margin-bottom: 24px;
  gap: 18px;
  align-items: center;
}
header h1 {
  font-size: 32px;
  font-weight: 650;
  line-height: 1.2;
  letter-spacing: -1px;
}
header .eyebrow {
  font-size: 12px;
  letter-spacing: 0.13em;
  color: #79877f;
  font-weight: 600;
  margin: 0 0 9px;
}
header .primary {
  font-size: 13px;
}
.workspace-bar {
  border-bottom: 1px solid var(--line);
  padding-bottom: 20px;
  margin-bottom: 24px;
  gap: 14px;
}
.month-picker {
  border: 0;
  background: transparent;
  padding: 5px 26px 5px 0;
  min-height: 36px;
  font-size: 15px;
  font-weight: 650;
  min-width: 195px;
  max-width: 240px;
}
.pill {
  background: #e5eee7;
  color: #5a7662;
  font-size: 12px;
  border-radius: 5px;
  font-weight: 550;
}
.workspace-bar #undo {
  border: 0;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  min-height: 32px;
}
.demo-banner {
  background: #edf2e9;
  border: 0;
  border-left: 3px solid #b6cda1;
  border-radius: 0 9px 9px 0;
  padding: 12px 17px;
  margin-bottom: 24px;
  gap: 16px;
}
.demo-banner b {
  font-weight: 600;
  font-size: 13px;
}
.demo-banner span {
  color: #71806b;
  font-size: 12px;
  margin-top: 1px;
}
.demo-banner .secondary {
  background: transparent;
  border-color: #cddac5;
  font-size: 12px;
  padding: 7px 12px;
  min-height: 34px;
}
.setup-prompt {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  padding: 18px 22px;
  border: 1px dashed #c8d8c7;
  border-radius: 12px;
  margin-bottom: 24px;
  background: #fbfdf9;
}
.setup-prompt b {
  font-size: 17px;
  font-weight: 600;
}
.setup-prompt p {
  font-size: 13px;
  margin: 3px 0 0;
}
.setup-prompt .secondary {
  white-space: nowrap;
}
.demo-banner:not([hidden]) ~ .view.active .setup-prompt {
  display: none;
}
.cards {
  gap: 14px;
  grid-template-columns: 1.2fr 1fr 1fr 0.85fr;
  margin-bottom: 25px;
}
.metric {
  padding: 23px 22px;
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 13px;
  min-height: 150px;
  box-shadow: none;
}
.metric.balance {
  background: #173d30;
  border: 1px solid #173d30;
}
.metric p {
  font-size: 12px;
  color: #78877e;
  font-weight: 550;
  margin: 0 0 13px;
}
.metric strong {
  font-size: 29px;
  letter-spacing: -1px;
  font-weight: 650;
  line-height: 1.25;
  margin-bottom: 15px;
  font-variant-numeric: tabular-nums;
}
.metric small {
  font-size: 12px;
  color: #87948c;
}
.metric.balance p,
.metric.balance small {
  color: #a4c1af;
}
.metric.balance strong {
  color: #e7f4d9;
}
.metric .positive,
.metric .negative {
  color: #87948c !important;
}
.dashboard-grid {
  grid-template-columns: minmax(0, 1.4fr) minmax(290px, 1fr);
  gap: 24px;
}
.panel {
  padding: 25px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: #fff;
  box-shadow: none;
  min-width: 0;
}
.panel h2 {
  font-size: 17px;
  font-weight: 650;
  color: #273b2f;
  margin: 0 0 4px;
}
.panel-heading {
  gap: 14px;
  align-items: flex-start;
}
.panel-heading p {
  font-size: 12px;
  color: #8b978f;
  margin: 4px 0 0;
}
.legend {
  font-size: 12px;
  gap: 5px;
  color: #89938d;
  white-space: nowrap;
}
.legend i {
  background: #318360;
  height: 6px;
  width: 6px;
}
.legend .expense-dot {
  background: #bcc9a0;
}
.chart {
  height: 225px;
  margin-top: 22px;
  border: 0;
  padding: 15px 0 23px;
  gap: 17px;
  background: repeating-linear-gradient(
    to top,
    transparent 0,
    transparent 49px,
    #eff3f0 50px,
    #eff3f0 51px
  );
}
.bar-group {
  padding-bottom: 0;
}
.bar {
  width: 24px;
  border-radius: 5px 5px 0 0;
  background: #318360;
  max-width: 38%;
}
.bar.out {
  background: #b8cba6;
}
.bar-label {
  bottom: -21px;
  font-size: 12px;
  color: #7f8c83;
}
.budget-row {
  margin-top: 23px;
}
.row-top {
  font-size: 13px;
  gap: 10px;
}
.row-top span:last-child {
  font-size: 12px;
  white-space: nowrap;
  color: #809085;
}
.progress {
  height: 5px;
  background: #f0f3ef;
  border-radius: 3px;
  margin-top: 11px;
}
.progress > i {
  background: #539976;
  border-radius: 3px;
}
.progress i.warn {
  background: #c6a169;
}
.budget-row small {
  font-size: 12px;
  margin-top: 7px;
  color: #94a096;
}
.goal-row b {
  font-weight: 600;
  font-size: 14px;
}
.goal-row .row-top {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.goal-row .row-top span {
  font-size: 12px;
  color: #809085;
}
.goal-row {
  margin-top: 22px;
}
.transaction-item {
  border-color: #edf1ed;
  padding: 17px 0;
  gap: 16px;
}
.transaction-item b,
.transaction-name {
  font-size: 13px;
  font-weight: 600;
}
.transaction-meta {
  font-size: 12px;
  color: #87948a;
  margin-top: 5px;
}
.transaction-item small {
  display: block;
  margin-top: 3px;
  color: #87948a;
  font-size: 12px;
}
.transaction-right {
  max-width: 51%;
}
.amount {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.2px;
}
.amount.expense {
  color: #3d4b41;
}
.amount.income {
  color: #27805a;
}
.row-actions {
  gap: 5px;
}
.row-actions .link-button {
  font-size: 12px;
  font-weight: 500;
  padding: 2px 4px;
  min-height: 29px;
}
.row-actions .danger {
  color: #9f747b;
}
.section-head {
  margin: 6px 0 20px;
  align-items: center;
}
.section-head h2 {
  display: none;
}
.section-head p {
  font-size: 14px;
  color: #87948a;
}
.section-head .primary {
  font-size: 13px;
}
.section-head:has(+ .table-panel) > .primary {
  display: none;
}
.view.active {
  animation: page-in 0.15s ease-out;
}
@keyframes page-in {
  from {
    opacity: 0.5;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.filters {
  display: grid;
  grid-template-columns: minmax(170px, 1.4fr) repeat(3, minmax(100px, 1fr)) auto;
  gap: 8px;
  padding-bottom: 17px;
}
.filters input,
.filters select {
  font-size: 12px;
  min-height: 39px;
  padding: 9px 10px;
  border-color: #e1e7e1;
  background: #fafcf9;
}
.filters .secondary {
  font-size: 12px;
  min-height: 39px;
  padding: 8px 12px;
}
.list-summary {
  font-size: 12px;
  color: #87948a;
  padding: 9px 0;
}
.table-panel {
  padding: 23px;
}
.bulk-toolbar {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
  padding: 8px 0 14px;
  border-bottom: 1px solid #edf1eb;
  font-size: 12px;
}
.bulk-toolbar .link-button {
  font-size: 12px;
  min-height: 30px;
}
.bulk-toolbar .secondary {
  margin-left: auto;
  font-size: 12px;
  min-height: 32px;
}
.selectable-transaction {
  display: flex;
  align-items: center;
  gap: 13px;
  border-bottom: 1px solid #edf1ed;
}
.selectable-transaction .transaction-item {
  flex: 1;
  border: 0;
  min-width: 0;
}
.tx-selection {
  margin: 0;
  display: grid;
  place-items: center;
}
.tx-selection input {
  width: 15px;
  height: 15px;
  min-height: 15px;
  accent-color: var(--blue);
}
.row-menu {
  position: relative;
  font-size: 12px;
}
.row-menu summary {
  cursor: pointer;
  list-style: none;
  color: #36654c;
  padding: 6px;
}
.row-menu summary::after {
  content: "⌄";
  margin-left: 5px;
}
.row-menu > div {
  position: absolute;
  right: 0;
  top: 100%;
  z-index: 7;
  display: grid;
  background: #fff;
  border: 1px solid var(--line);
  box-shadow: 0 8px 28px #132c2420;
  border-radius: 9px;
  min-width: 160px;
  padding: 6px;
  text-align: left;
}
.row-menu[open] {
  z-index: 8;
}
.row-menu .link-button {
  text-align: left;
  font-size: 12px;
  padding: 8px 10px;
  min-height: 34px;
}
.row-menu .link-button:hover {
  background: #edf5ef;
}
.tag {
  font-family: var(--font);
  font-style: normal;
  font-size: 12px;
  background: #f0f4ed;
  color: #738069;
  padding: 3px 7px;
  margin-top: 4px;
  border-radius: 4px;
}
.budget-grid,
.goals-grid,
.accounts-grid,
.debt-grid {
  gap: 18px;
}
.budget-card,
.goal-card,
.account-card,
.debt-card {
  border-radius: 13px;
  border: 1px solid var(--line);
  padding: 24px;
  box-shadow: none;
}
.budget-card .budget-row {
  margin-top: 0;
}
.budget-card .row-actions,
.goal-card .row-actions,
.account-card .row-actions {
  margin-top: 20px;
  border-top: 1px solid #edf1eb;
  padding-top: 13px;
}
.goal-icon {
  background: #eef4e7;
  color: #648159;
  border-radius: 9px;
  width: 34px;
  height: 34px;
  font-size: 20px;
}
.account-card {
  border-top: 3px solid #658f76;
}
.account-card:nth-child(2) {
  border-top-color: #aabc89;
}
.account-card:nth-child(3) {
  border-top-color: #abbcac;
}
.account-card h3 {
  font-size: 15px;
  font-weight: 600;
}
.account-card strong {
  font-size: 30px;
  font-weight: 650;
  letter-spacing: -1px;
  margin: 21px 0 7px;
}
.account-card small {
  font-size: 12px;
}
.archived-account {
  background: #f6f7f5;
  opacity: 0.75;
}
.debt-card {
  border-top: 3px solid #b48c91;
}
.debt-card.card-credit {
  border-top-color: #a89971;
}
.debt-stat {
  font-size: 30px;
  letter-spacing: -1px;
  margin: 20px 0 10px;
}
.summary-card {
  padding: 21px;
  border: 1px solid var(--line);
  border-radius: 11px;
}
.summary-card p {
  font-size: 12px;
  color: #859288;
  margin-bottom: 8px;
}
.summary-card strong {
  font-size: 25px;
  font-weight: 650;
  letter-spacing: -0.7px;
  line-height: 1.3;
}
.summary-card small {
  font-size: 12px;
  color: #8c9a8f;
}
.mini-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 14px;
  margin: 20px 0;
}
.mini-metrics .summary-card {
  background: #f8faf6;
  border: 0;
  padding: 18px;
}
.mini-metrics .summary-card strong {
  font-size: 24px;
}
.report-cards,
.wealth-cards,
.cash-cards,
.debt-summary {
  gap: 16px;
  margin-bottom: 24px;
}
.feature-panel {
  margin-top: 24px;
}
.report-grid {
  gap: 24px;
}
.annual-chart {
  background: repeating-linear-gradient(
    to top,
    transparent 0,
    transparent 49px,
    #eff3f0 50px,
    #eff3f0 51px
  );
  border: 0;
  padding-bottom: 24px;
  margin-top: 12px;
}
.annual-chart .bar {
  width: 16px;
}
.annual-chart .bar-label {
  font-size: 12px;
}
.breakdown-row {
  font-size: 13px;
  grid-template-columns: 105px 1fr auto;
  gap: 14px;
}
.breakdown-row b {
  font-size: 12px;
  font-weight: 600;
}
.alert {
  background: #f8f2e9;
  border: 0;
  border-left: 3px solid #cbaa77;
  font-size: 13px;
  color: #695d45;
  border-radius: 0 7px 7px 0;
}
.alert.good {
  background: #eff5e9;
  color: #567747;
  border-color: #abc191;
}
.alert.danger {
  background: #fcf0f0;
  color: #945a64;
  border-color: #cb8f9a;
}
.insight-hero {
  background: #173d30;
  color: #e7f4d9;
}
.insight-hero h2 {
  color: #e7f4d9;
}
.insight-hero p {
  color: #a8c1b1;
}
.insight-hero .insight-label {
  color: #aec7b5;
}
.insight-hero strong {
  font-size: 32px;
}
.forecast {
  background: #f1f6ed;
}
.forecast .insight-label {
  color: #66805b;
  font-size: 12px;
}
.forecast strong {
  font-size: 37px;
  font-weight: 650;
  letter-spacing: -1px;
}
.forecast-rule {
  background: #d5e1cc;
}
.comparison-row,
.comparison-head {
  display: grid;
  grid-template-columns: minmax(130px, 1.5fr) repeat(3, minmax(90px, 1fr));
  gap: 14px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid #edf1eb;
  font-size: 13px;
}
.comparison-head {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #8a988e;
  margin-top: 20px;
}
.comparison-row b {
  font-weight: 600;
}
.comparison-row span {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.comparison-head span:not(:first-child) {
  text-align: right;
}
.rank-row {
  display: flex;
  align-items: center;
  gap: 17px;
  padding: 14px 0;
  border-bottom: 1px solid #edf1eb;
}
.rank-row > span {
  color: #acb7ae;
  font-size: 12px;
}
.rank-row > div {
  flex: 1;
}
.rank-row b {
  font-size: 13px;
  font-weight: 600;
}
.rank-row small {
  display: block;
  color: #94a096;
  font-size: 12px;
}
.rank-row strong {
  font-size: 14px;
  font-weight: 600;
}
.annual-cost {
  font-size: 35px;
  font-weight: 650;
  letter-spacing: -1px;
  margin: 22px 0;
}
.annual-cost small {
  display: block;
  font-size: 12px;
  letter-spacing: 0;
  font-weight: 400;
  color: #89978a;
  margin-top: 5px;
}
.inline-field {
  display: flex;
  gap: 12px;
  align-items: center;
  font-size: 12px;
  color: #7c8c7f;
  margin-top: 18px;
}
.inline-field select {
  width: 135px;
  min-height: 37px;
  font-size: 13px;
}
.forecast-graph,
.wealth-timeline {
  height: 175px;
  display: flex;
  align-items: end;
  gap: 6px;
  margin: 25px 0 35px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
  background: repeating-linear-gradient(
    to top,
    transparent 0,
    transparent 39px,
    #eff3f0 40px,
    #eff3f0 41px
  );
}
.forecast-column,
.wealth-timeline > div {
  height: 100%;
  position: relative;
  flex: 1;
  display: flex;
  align-items: end;
  justify-content: center;
  min-width: 0;
}
.forecast-column i,
.wealth-timeline i {
  display: block;
  width: 70%;
  max-width: 35px;
  background: #689d79;
  border-radius: 3px 3px 0 0;
}
.forecast-column small,
.wealth-timeline small {
  position: absolute;
  top: calc(100% + 6px);
  font-size: 12px;
  color: #90a094;
  white-space: nowrap;
}
.below-zero {
  background: #ba7b82 !important;
}
.financial-calendar {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 12px;
  max-height: 540px;
  overflow: auto;
}
.calendar-block {
  background: #fafcf8;
  border: 1px solid var(--line);
  border-radius: 9px;
  padding: 14px;
}
.calendar-block-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: 12px;
  margin-bottom: 10px;
}
.calendar-event {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 0;
  font-size: 12px;
  border-top: 1px solid #edf1eb;
}
.calendar-event small {
  display: block;
  font-size: 12px;
  color: #90a094;
}
.calendar-event > b {
  white-space: nowrap;
  font-weight: 600;
}
.activity-entry {
  border-bottom: 1px solid #edf1eb;
  padding: 13px 0;
  font-size: 13px;
}
.activity-entry summary {
  cursor: pointer;
  list-style: none;
}
.activity-entry b {
  font-weight: 550;
}
.activity-entry small {
  display: block;
  font-size: 12px;
  color: #93a094;
  margin-top: 3px;
}
.activity-entry p {
  font-size: 12px;
  margin: 8px 0 0 12px;
}
.backup-reminder {
  display: flex;
  gap: 18px;
  justify-content: space-between;
  align-items: center;
  background: #f1f5e9;
  border-radius: 11px;
  padding: 18px 21px;
  margin-bottom: 22px;
}
.backup-reminder b {
  font-size: 14px;
}
.backup-reminder span {
  display: block;
  font-size: 12px;
  color: #829176;
  margin-top: 2px;
}
.settings-grid {
  gap: 24px;
}
.settings-grid h2 {
  font-size: 17px;
}
.settings-grid p,
.help-list {
  font-size: 13px;
  color: #839080;
}
.settings-label {
  font-size: 13px;
  color: #7d8b7f;
}
.help-list li {
  margin: 10px 0;
}
kbd {
  font-family: var(--font);
  border: 1px solid #d9e2d6;
  background: #f5f8f1;
  border-radius: 4px;
  padding: 2px 5px;
