body {
  font-size: 1rem;
  background: #f5f7f9;
  color: #172c34;
}
.sidebar {
  background: #112f36;
  width: 216px;
}
.sidebar nav {
  gap: 10px;
  padding-top: 38px;
}
.sidebar .nav-link {
  min-height: 48px;
  font-size: 0.9375rem;
  border-radius: 10px;
}
.sidebar .nav-link.active {
  background: #e5f3ef;
  color: #123d36;
}
.nav-group {
  display: none;
}
.area-tabs {
  display: flex;
  gap: 8px;
  padding: 0 0 22px;
  flex-wrap: wrap;
}
.area-tabs[hidden] {
  display: none;
}
.area-tabs button {
  background: transparent;
  color: #586b74;
  border: 0;
  padding: 10px 16px;
  border-radius: 8px;
  font-size: 0.9375rem;
  cursor: pointer;
}
.area-tabs button.active {
  color: #0c5947;
  background: #e1eee9;
  font-weight: 650;
}
.decision-panel {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 44px;
  padding: 36px;
  margin: 24px 0;
  background: #fff;
  border: 1px solid #dce5e9;
  border-radius: 18px;
  box-shadow: 0 8px 30px #172c3405;
}
.eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  color: #59737a;
  margin: 0 0 16px;
}
.decision-copy h2 {
  font-size: 1.375rem;
  margin: 0;
  font-weight: 550;
}
.spending-number {
  display: block;
  font-size: clamp(2.4rem, 4vw, 3.6rem);
  letter-spacing: -0.045em;
  line-height: 1.25;
  margin: 12px 0;
  color: #104b40;
  font-variant-numeric: tabular-nums;
}
.decision-copy > p:not(.eyebrow),
.calculation p {
  color: #526770;
  line-height: 1.65;
}
.decision-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 24px;
}
.calculation {
  border-left: 1px solid #e4eaec;
  padding-left: 32px;
}
.calculation h3 {
  font-size: 1rem;
  margin: 0 0 18px;
}
.calculation dl {
  margin: 0;
}
.calculation dl > div {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 0;
  border-bottom: 1px solid #edf1f3;
  font-size: 0.875rem;
}
.calculation dd {
  margin: 0;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.calculation p {
  font-size: 0.8125rem;
}
.attention-panel {
  margin-bottom: 24px;
}
.attention-row {
  display: flex;
  gap: 20px;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid #edf1f3;
}
.attention-row:last-child {
  border-bottom: 0;
}
.attention-row b {
  font-size: 0.9375rem;
  font-weight: 600;
}
.attention-row p,
.quiet-state {
  color: #536870;
  font-size: 0.875rem;
  line-height: 1.6;
  margin: 5px 0;
}
.attention-row button {
  flex-shrink: 0;
}
#closingGuide {
  margin-bottom: 24px;
}
#closingGuide > p {
  line-height: 1.7;
}
.scenario-result strong {
  display: block;
  font-size: 2.4rem;
  color: #104b40;
}
.panel p,
.transaction-main,
.transaction-description,
button,
input,
select,
label {
  font-size: 0.9375rem;
}
.transaction-meta,
.metric > p,
.metric small,
.panel small {
  font-size: 0.8125rem;
}
#setupPrompt {
  margin-top: 20px;
}
#dashboard .metric:first-child {
  background: #fff;
  color: #172c34;
}
#dashboard .metric:first-child strong {
  color: #172c34;
}
#dashboard .metric:first-child p,
#dashboard .metric:first-child small {
