.panel h2,
.panel h3 {
  line-height: 1.3;
}
.amount,
.metric strong,
td {
  font-variant-numeric: tabular-nums;
}
button,
a,
summary,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}
:is(button, a, summary, input, select, textarea):focus-visible {
  outline: 3px solid #738f43;
  outline-offset: 3px;
}
body[data-theme="dark"] :focus-visible {
  outline-color: #c8dda1;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
dialog form {
  padding: 26px 28px;
}
dialog label {
  margin: 12px 0;
  gap: 6px;
}
dialog .two-cols {
  gap: 12px;
}
dialog input,
dialog select,
dialog textarea {
  min-height: 44px;
}
dialog textarea {
  resize: vertical;
}
dialog .optional-fields {
  margin: 14px 0 4px;
}
dialog .full {
  margin-top: 10px;
}
.filter-message {
  padding: 18px;
  border-left: 3px solid var(--orange);
  background: var(--surface-soft);
}
.bulk-toolbar {
  gap: 10px;
  flex-wrap: wrap;
  border-radius: 12px;
  background: var(--surface-soft);
  padding: 12px 14px;
}
#bulkCount {
  font-size: 13px;
  font-weight: 600;
}
.review-heading {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  margin: 8px 0 26px;
}
.review-heading h2 {
  font-size: clamp(25px, 3vw, 34px);
  line-height: 1.2;
  margin: 5px 0 12px;
}
.review-heading p {
  max-width: 680px;
  margin: 8px 0;
}
.eyebrow {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 700;
}
.review-heading > button {
  flex-shrink: 0;
}
.review-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}
.review-metric {
  background: var(--paper);
  border: 1px solid var(--review-border);
  border-radius: 16px;
  padding: 24px;
  min-width: 0;
}
.review-metric > span,
.review-metric small {
  display: block;
  color: var(--muted);
}
.review-metric > span {
  font-size: 13px;
  font-weight: 600;
}
.review-metric strong {
  display: block;
  font-size: clamp(25px, 3vw, 34px);
  margin: 10px 0;
  line-height: 1.2;
  overflow-wrap: anywhere;
}
.review-metric small {
  font-size: 12px;
  line-height: 1.5;
}
.review-card {
  padding: 26px;
  margin: 0 0 20px;
}
.review-card h3 {
  margin: 0 0 14px;
  font-size: 19px;
}
.review-card > p {
  max-width: 800px;
}
.review-card > button {
  margin: 8px 8px 0 0;
}
.review-card details {
  margin-top: 16px;
}
.review-card summary,
.inline-options summary {
  cursor: pointer;
  font-weight: 600;
  padding: 10px 0;
}
.review-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  padding: 16px 0;
  border-top: 1px solid var(--review-border);
}
.review-line > div {
  min-width: 0;
  overflow-wrap: anywhere;
}
.review-line small {
  display: block;
  margin-top: 4px;
  color: var(--muted);
}
.review-line p {
  margin: 5px 0;
}
.review-line > strong {
  white-space: nowrap;
}
.review-deviation {
  border-top: 1px solid var(--review-border);
  padding: 6px 0;
}
.review-deviation > summary {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}
.review-deviation > summary::before {
  content: "+";
  flex: 0 0 14px;
  color: var(--muted);
}
.review-deviation[open] > summary::before {
  content: "−";
}
.review-deviation > summary span {
  flex: 1;
}
.review-deviation > summary b {
  font-size: 13px;
  text-align: right;
}
.review-deviation .transaction-item {
  background: var(--surface-soft);
  border-radius: 10px;
  margin: 6px 0;
  padding: 12px;
}
.review-status {
  border-radius: 10px;
  padding: 12px 16px;
  background: var(--surface-soft);
}
.inbox-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  padding: 22px 26px;
  margin: 14px 0;
}
.inbox-item h3 {
  margin: 0 0 6px;
  font-size: 16px;
  overflow-wrap: anywhere;
}
.inbox-item p {
  margin: 0;
}
.review-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  justify-content: flex-start;
}
.inline-options {
  font-size: 12px;
}
.inline-options[open] {
  padding: 0 10px 8px;
  background: var(--surface-soft);
  border-radius: 10px;
}
.inline-options button {
  display: block;
  padding: 8px;
  text-align: left;
}
.preserve-lines {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.planning-table th {
  font-size: 12px;
}
.planning-table tbody tr:hover {
  background: var(--surface-soft);
}
.planning-table thead {
  background: var(--surface-soft);
}
body[data-density="compact"] .review-metric,
body[data-density="compact"] .review-card {
  padding: 18px;
}
body[data-theme="dark"] .bulk-toolbar,
body[data-theme="dark"] .review-metric {
  background: #192d36;
  color: var(--ink);
}
body[data-theme="dark"] .review-deviation summary {
  color: var(--ink);
}
@media (max-width: 760px) {
  .review-heading {
    display: block;
  }
}
@media (max-width: 760px) {
  .review-heading > button {
    margin-top: 10px;
  }
}
@media (max-width: 760px) {
  .review-metrics {
    gap: 10px;
  }
}
@media (max-width: 760px) {
  .review-metric {
    padding: 16px;
  }
}
@media (max-width: 760px) {
  .review-metric strong {
    font-size: 23px;
  }
}
@media (max-width: 760px) {
  .inbox-item {
    display: block;
    padding: 18px;
  }
}
@media (max-width: 760px) {
  .review-actions {
    margin-top: 14px;
  }
}
@media (max-width: 480px) {
  .review-metrics {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 480px) {
  .review-metric {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 6px 12px;
    align-items: center;
  }
}
@media (max-width: 480px) {
  .review-metric strong {
    margin: 0;
    font-size: 24px;
  }
}
@media (max-width: 480px) {
  .review-metric small {
    grid-column: 1 / -1;
  }
}
@media (max-width: 480px) {
  .review-card {
    padding: 18px;
  }
}
@media (max-width: 480px) {
  .review-deviation > summary {
    flex-wrap: wrap;
    gap: 8px;
  }
}
@media (max-width: 480px) {
  .review-deviation > summary b {
    flex-basis: 100%;
    text-align: left;
    padding-left: 22px;
  }
}
@media (max-width: 480px) {
  .review-line {
    gap: 12px;
    flex-wrap: wrap;
  }
}
@media (max-width: 480px) {
  .review-line > button {
    min-height: 42px;
  }
}
@media (max-width: 480px) {
  dialog form {
    padding: 22px 18px;
  }
}
@media (max-width: 480px) {
  .bulk-toolbar button {
    min-height: 40px;
  }
}
#monthPicker[hidden] {
  display: none !important;
}
.period-pair {
  display: flex;
  flex-shrink: 0;
  gap: 10px;
  align-items: center;
}
.period-pair label {
  display: grid;
  gap: 4px;
  font-size: 12px;
  color: var(--muted);
}
.period-pair select {
  min-height: 40px;
  min-width: 92px;
  max-width: 170px;
}
.inline-global-search {
  position: relative;
  min-width: 220px;
  flex: 1 1 220px;
  width: min(100%, 300px);
  margin-left: auto;
}
.workspace-bar {
  flex-wrap: wrap;
}
#periodMonth {
  min-width: 135px;
}
.inline-search-label {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 9px;
}
.inline-search-label span {
  font-size: 26px;
  color: var(--muted);
}
.inline-search-label input {
  border: 0;
  box-shadow: none;
  min-width: 0;
  width: 100%;
  background: transparent;
}
.inline-search-results {
  position: absolute;
  z-index: 60;
  top: calc(100% + 6px);
  right: 0;
  width: min(420px, 80vw);
  max-height: 360px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
  box-shadow: 0 12px 30px #0002;
  padding: 10px;
}
.inline-search-results .search-result {
  width: 100%;
  text-align: left;
}
.movement-note {
  font-size: 12px;
  line-height: 1.5;
  margin-top: 5px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--muted);
}
.note-blue {
  color: #195ba4;
}
.note-green {
  color: #15704b;
}
.note-purple {
  color: #7546a5;
}
.note-orange {
  color: #975000;
}
.note-red {
  color: #b12d3d;
}
body[data-theme="dark"] .note-blue {
  color: #91c2ff;
}
body[data-theme="dark"] .note-green {
  color: #8cdbb8;
}
body[data-theme="dark"] .note-purple {
  color: #d0adff;
}
body[data-theme="dark"] .note-orange {
  color: #ffc185;
}
body[data-theme="dark"] .note-red {
  color: #ff9eab;
}
.category-directory {
  margin: 18px 0;
  border-top: 1px solid var(--line);
}
.category-directory-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--line);
  padding: 13px 0;
}
.category-directory-row small {
  display: block;
  color: var(--muted);
  margin-top: 4px;
}
.category-directory-row.is-subcategory {
  padding-left: 22px;
  border-left: 2px solid var(--line);
}
.category-tools summary {
  cursor: pointer;
  padding: 12px 0;
}
.equilibrio-studio .advanced-search {
  padding: 0;
  margin: 10px 0;
  border: 0;
  box-shadow: none;
  background: transparent;
}
.equilibrio-studio .advanced-search details {
  padding: 0;
  border: 0;
}
.equilibrio-studio .advanced-search summary {
  display: list-item;
  padding: 8px 0;
  font-size: 13px;
  color: var(--muted);
}
.equilibrio-studio .advanced-search .filter-grid {
  gap: 10px;
  padding: 12px 0;
}
@media (max-width: 600px) {
  .inline-global-search {
    width: 100%;
    margin: 0;
  }
}
@media (max-width: 600px) {
  .inline-search-results {
    width: 100%;
  }
}
@media (max-width: 600px) {
  .category-directory-row {
    align-items: flex-start;
    flex-direction: column;
  }
}
@media (max-width: 600px) {
  .category-directory-row .row-actions {
    flex-wrap: wrap;
  }
}
@media (max-width: 600px) {
  .period-pair select {
    max-width: 155px;
  }
}
.workflow-detail,
.context-help {
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 14px 16px;
  margin: 16px 0;
  background: var(--paper);
  overflow-wrap: anywhere;
}
.workflow-detail summary,
.context-help summary {
  cursor: pointer;
  font-weight: 600;
  line-height: 1.5;
}
.workflow-detail p,
.context-help p {
  line-height: 1.65;
}
.import-comparison {
  grid-column: 1 / -1;
  margin: 4px 0;
}
.comparison-scroll {
  overflow-x: auto;
}
.comparison-table {
  width: 100%;
  border-collapse: collapse;
}
.comparison-table th,
.comparison-table td {
  padding: 12px;
  text-align: right;
  border-bottom: 1px solid var(--line);
  font-variant-numeric: tabular-nums;
}
.comparison-table th:first-child {
  text-align: left;
}
.comparison-table small {
  display: block;
  font-weight: normal;
}
.change-preview {
  max-height: 40vh;
  overflow: auto;
  border-block: 1px solid var(--line);
}
.change-preview article {
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}
.change-preview p {
  margin: 6px 0;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.change-preview span {
  display: inline-block;
  min-width: 65px;
  color: var(--muted);
}
.workflow-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 12px;
}
.workflow-tabs button {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 14px;
  background: var(--paper);
  color: var(--ink);
  cursor: pointer;
  min-height: 44px;
}
.workflow-tabs button[aria-pressed="true"] {
  background: var(--ink);
  color: var(--paper);
  border-color: var(--ink);
}
.workflow-tabs span {
  opacity: 0.75;
  margin-left: 6px;
}
#agendaRows .transaction-item {
  flex-wrap: wrap;
  gap: 12px;
}
.agenda-history {
  flex-basis: 100%;
  padding: 8px 0;
  color: var(--muted);
}
.agenda-history summary {
  cursor: pointer;
}
.agenda-state {
  margin: 0 8px 16px;
  color: var(--muted);
  font-size: 14px;
}
.opening-guide {
  border-left: 3px solid var(--blue);
  padding: 8px 14px;
  background: var(--canvas);
  line-height: 1.6;
}
.settings-disclosure {
  padding: 0;
  margin: 0;
  align-self: start;
}
.settings-disclosure > summary {
  padding: 20px;
}
.settings-disclosure > .panel {
  border: 0;
  margin: 0;
  box-shadow: none;
  padding-top: 0;
}
.settings-disclosure > .panel > h2:first-child {
  display: none;
}
@media (max-width: 600px) {
  .workflow-tabs {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 600px) {
  .workflow-tabs button {
    padding: 10px 6px;
  }
}
@media (max-width: 600px) {
  #agendaRows .transaction-right {
    width: 100%;
    text-align: left;
  }
}
@media (max-width: 600px) {
  #agendaRows .row-actions {
    justify-content: flex-start;
    flex-wrap: wrap;
  }
}
body.equilibrio-studio {
  --canvas: #f3f5f8;
  --ink: #172b36;
  --muted: #596c77;
  --line: #dde5eb;
  --paper: #fff;
  --blue: #116e59;
  font-size: 16px;
}
.equilibrio-studio main {
  background: var(--canvas);
}
.equilibrio-studio .sidebar {
  background: #102c38;
}
.equilibrio-studio .brand {
  letter-spacing: -0.045em;
}
.equilibrio-studio .panel,
.equilibrio-studio .account-card,
.equilibrio-studio .goal-card,
.equilibrio-studio .budget-card {
  border-radius: 14px;
  border-color: var(--line);
  box-shadow: 0 3px 16px #16334604;
}
.equilibrio-studio .section-head h2 {
  font-size: 26px;
}
.equilibrio-studio button,
.equilibrio-studio label,
.equilibrio-studio summary {
  font-size: 14px;
}
.equilibrio-studio .transaction-item b {
  font-size: 15px;
}
.equilibrio-studio .transaction-item {
  padding: 16px 8px;
}
.equilibrio-studio .transaction-meta {
  font-size: 12px;
}
.equilibrio-studio .amount {
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.015em;
}
.equilibrio-studio #dashboard.active {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(300px, 1fr);
  gap: 22px;
  align-items: start;
}
.equilibrio-studio #dashboard > * {
  grid-column: 1 / -1;
  margin-top: 0;
  margin-bottom: 0;
}
.equilibrio-studio #dashboard #decisionPanel,
.equilibrio-studio #dashboard #salaryPlan {
  grid-column: 1;
  grid-row: 1;
  padding: 28px;
  display: block;
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 4px solid #187e65;
  border-radius: 14px;
}
.equilibrio-studio #dashboard #attentionPanel {
  grid-column: 2;
  grid-row: 1;
  padding: 22px;
}
.equilibrio-studio #attentionPanel .section-head {
  margin: 0 0 12px;
}
.equilibrio-studio #attentionPanel .attention-row {
  padding: 12px 0;
}
.equilibrio-studio #attentionPanel .attention-row p {
  font-size: 12px;
  margin: 4px 0;
}
.equilibrio-studio #attentionPanel .attention-row b {
  font-size: 14px;
}
.equilibrio-studio #attentionPanel .secondary {
  padding: 7px 10px;
  font-size: 12px;
}
.equilibrio-studio #attentionPanel .daily-backup-actions {
  gap: 6px;
  margin-top: 12px;
}
.equilibrio-studio #dailyBackupHint {
  font-size: 12px;
  margin-bottom: 0;
}
.equilibrio-studio .decision-explanation {
  border-top: 1px solid var(--line);
  margin-top: 20px;
  padding-top: 8px;
}
.equilibrio-studio .decision-explanation > summary {
  padding: 10px 0;
  font-weight: 600;
  cursor: pointer;
}
.equilibrio-studio .decision-explanation .calculation {
  border: 0;
  padding: 12px 0 0;
}
.equilibrio-studio #decisionPanel h2 {
  font-size: 25px;
  margin-top: 12px;
}
.equilibrio-studio #dashboard .cards {
  gap: 14px;
}
.equilibrio-studio #dashboard .metric {
  border-radius: 12px;
  box-shadow: none;
  padding: 20px;
}
.equilibrio-studio #dashboard .metric strong {
  font-size: 29px;
}
.equilibrio-studio .planning-table {
  border: 1px solid var(--line);
  border-radius: 12px;
}
.equilibrio-studio .planning-table th,
.equilibrio-studio .planning-table td {
  font-size: 14px;
  padding: 14px;
}
body.equilibrio-studio[data-theme="dark"] {
  --canvas: #101e28;
  --paper: #192f3a;
  --ink: #edf3f7;
  --muted: #b9cad5;
  --line: #354d5d;
}
body.equilibrio-studio[data-theme="dark"] main {
  background: var(--canvas);
}
body.equilibrio-studio[data-theme="dark"] .decision-copy > p:not(.eyebrow),
body.equilibrio-studio[data-theme="dark"] .calculation p,
body.equilibrio-studio[data-theme="dark"] #dashboard .metric p,
body.equilibrio-studio[data-theme="dark"] #dashboard .metric small {
  color: var(--muted);
}
@media (max-width: 1050px) {
  .equilibrio-studio #dashboard.active {
    grid-template-columns: minmax(0, 1fr);
  }
}
@media (max-width: 1050px) {
  .equilibrio-studio #dashboard #attentionPanel {
    grid-column: 1;
    grid-row: auto;
  }
}
@media (max-width: 600px) {
  .equilibrio-studio #dashboard #decisionPanel,
  .equilibrio-studio #dashboard #salaryPlan {
    padding: 22px;
  }
}
@media (max-width: 600px) {
  .equilibrio-studio #dashboard .metric strong {
    font-size: 23px;
  }
}
@media (max-width: 600px) {
  .equilibrio-studio .planning-table th,
  .equilibrio-studio .planning-table td {
    padding: 12px 8px;
  }
}
#transactionsTable .transaction-columns,
#transactionsTable .transaction-item {
  display:grid;
  grid-template-columns:minmax(210px,1.35fr) minmax(150px,.9fr) minmax(220px,1.15fr) minmax(190px,.8fr);
  gap:14px;
  align-items:center;
}
#transactionsTable .transaction-columns {
  padding:8px 0 9px;
  border-bottom:1px solid var(--line);
  color:var(--muted);
  font-size:10px;
  font-weight:700;
  letter-spacing:.045em;
  text-transform:uppercase;
}
#transactionsTable .transaction-item { padding:11px 0; }
#transactionsTable .tx-beneficiary {font-size:12px; overflow-wrap:anywhere;}
#transactionsTable .tx-details {display:grid; gap:2px; font-size:11px; color:var(--muted);}
#transactionsTable .transaction-right {max-width:none; min-width:0; align-items:flex-end;}
#transactionsTable .row-actions {justify-content:flex-end; flex-wrap:wrap; margin-top:3px;}
#transactionsTable .row-actions .secondary,
#transactionsTable .row-actions .link-button,
.compact-action {min-height:25px!important; padding:2px 6px!important; font-size:11px!important; border-radius:6px!important;}
.equilibrio-studio .advanced-search summary {padding:5px 0; font-size:12px;}
.equilibrio-studio .advanced-search .filter-grid {grid-template-columns:repeat(6,minmax(90px,1fr)); gap:6px; padding:7px 0;}
.equilibrio-studio .advanced-search .filter-grid label {margin:0; font-size:10px;}
