.receipt-indicator{
  display:inline-flex;
  align-items:center;
  gap:4px;
  margin:5px 6px 0 0;
  padding:3px 7px;
  border-radius:999px;
  border:1px solid var(--line);
  font-size:10px;
  line-height:1.2;
  font-weight:700;
  vertical-align:middle;
  white-space:nowrap;
}
.receipt-indicator.has-receipt{
  color:var(--green);
  background:color-mix(in srgb,var(--green) 10%,var(--paper));
  border-color:color-mix(in srgb,var(--green) 30%,var(--line));
}
.receipt-indicator.no-receipt{
  color:var(--muted);
  background:var(--canvas);
}
.transaction-item[data-can-receipt="1"]{
  position:relative;
  transition:border-color .16s ease,box-shadow .16s ease,background-color .16s ease;
}
.transaction-item.receipt-drop-target{
  border-color:var(--blue)!important;
  background:color-mix(in srgb,var(--blue) 7%,var(--paper))!important;
  box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--blue) 45%,transparent)!important;
}
.transaction-item.receipt-drop-target::after{
  content:"Largar para anexar comprovativo";
  position:absolute;
  inset:5px 8px auto auto;
  z-index:2;
  padding:4px 8px;
  border-radius:7px;
  background:var(--blue);
  color:#fff;
  font-size:10px;
  font-weight:700;
  pointer-events:none;
}
.receipt-row-highlight{
  animation:receipt-row-flash 1.8s ease;
}
@keyframes receipt-row-flash{
  0%,35%{box-shadow:inset 0 0 0 2px var(--blue);background:color-mix(in srgb,var(--blue) 8%,var(--paper));}
  100%{box-shadow:none;background:var(--paper);}
}
#documentsHub .documents-panel{padding:20px!important;}
.document-metrics{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
  margin:0 0 16px;
}
.document-metrics article{
  min-width:0;
  padding:12px 14px;
  border:1px solid var(--line);
  border-radius:10px;
  background:var(--canvas);
}
.document-metrics span,.document-metrics small{display:block;color:var(--muted);font-size:10px;}
.document-metrics strong{display:block;margin:3px 0;font-size:17px;overflow:hidden;text-overflow:ellipsis;}
.document-filter-grid{
  display:grid;
  grid-template-columns:minmax(190px,1.6fr) 90px repeat(2,minmax(135px,.8fr)) repeat(2,minmax(110px,.65fr)) minmax(115px,.65fr);
  gap:8px;
  align-items:end;
  margin:0 0 10px;
}
.document-filter-grid label{margin:0!important;min-width:0;font-size:10px!important;}
.document-filter-grid input,.document-filter-grid select{min-height:34px;padding:6px 8px;font-size:12px;max-width:none!important;}
.document-toolbar{margin:4px 0 14px!important;display:flex;gap:8px;flex-wrap:wrap;}
.document-list{border-top:1px solid var(--line);}
.document-row{gap:14px!important;}
.document-main{min-width:0;}
.document-title{display:flex;align-items:center;gap:7px;min-width:0;}
.document-title b{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.document-type-badge{
  flex:0 0 auto;
  display:inline-flex;
  align-items:center;
  padding:3px 6px;
  border-radius:6px;
  border:1px solid var(--line);
  font-size:9px;
  font-weight:800;
  letter-spacing:.04em;
}
.document-type-badge.pdf{color:var(--red);background:color-mix(in srgb,var(--red) 8%,var(--paper));}
.document-type-badge.image{color:var(--blue);background:color-mix(in srgb,var(--blue) 8%,var(--paper));}
.documents-missing{margin-top:18px!important;padding:13px 14px!important;border:1px solid var(--line)!important;border-radius:10px!important;}
.documents-missing>summary{font-weight:700;cursor:pointer;}
.documents-missing>p{margin:8px 0 12px!important;}
body[data-theme="dark"] .receipt-indicator.no-receipt,
body[data-theme="dark"] .document-metrics article{background:color-mix(in srgb,var(--paper) 85%,#000)!important;}
