.casa-beta-badge{white-space:nowrap;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#126247;background:#d9efe2;border-radius:999px;padding:6px 9px}
.casa-toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:0 0 16px}
.casa-toolbar .casa-search{min-width:220px;flex:1}
.casa-toolbar select{min-width:180px}
.casa-toolbar .secondary,.casa-toolbar .primary{min-height:40px}
.casa-summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin:0 0 18px}
.casa-summary-card{background:var(--paper);border:1px solid var(--line);border-radius:13px;padding:16px}
.casa-summary-card span{display:block;color:var(--muted);font-size:12px}
