.casa-store{display:flex;align-items:center;gap:9px;font-weight:650}
.casa-store-logo{display:grid;place-items:center;width:28px;height:28px;border-radius:8px;background:#e7f3ed;color:#136247;font-size:12px;font-weight:800;flex:none}
.casa-status{display:inline-flex;align-items:center;border-radius:999px;padding:4px 8px;font-size:11px;font-weight:700;background:#e1f3e7;color:#146142}
.casa-origin-pill{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:4px 8px;font-size:11px;background:#ecf5f0;color:#285d49}
