}
.summary-chart-legend .income{color:var(--summary-green);}
.summary-chart-legend .expense{color:var(--summary-red);}
.summary-svg-chart,.summary-bars{
  width:100%!important;
  height:232px!important;
  min-height:232px!important;
  margin:0!important;
  padding:0!important;
  border:0!important;
  display:block!important;
  overflow:hidden;
}
.summary-svg-chart svg,.summary-bars svg{display:block;width:100%;height:100%;overflow:visible;}
.summary-grid-line{stroke:var(--line);stroke-width:1;opacity:.7;}
.summary-axis-label,.summary-axis-month{fill:var(--muted);font-size:10px;font-family:inherit;}
.summary-axis-month{text-transform:capitalize;}
.summary-line-area{fill:url(#summaryBalanceFill);}
.summary-line-path{fill:none;stroke:var(--summary-green);stroke-width:3;stroke-linecap:round;stroke-linejoin:round;}
.summary-line-point{fill:var(--summary-green);stroke:var(--paper);stroke-width:1.5;}
.summary-bar-income{fill:var(--summary-green);}
.summary-bar-expense{fill:var(--summary-red);}
.summary-donut-layout{
  min-height:224px;
  display:grid;
  grid-template-columns:minmax(138px,.95fr) minmax(150px,1.05fr);
  align-items:center;
  gap:18px;
}
.summary-donut{
  width:min(166px,100%);
  aspect-ratio:1;
  margin:auto;
  border-radius:50%;
  background:var(--summary-donut);
  position:relative;
  display:grid;
  place-items:center;
}
.summary-donut:after{
  content:"";
  position:absolute;
  inset:27%;
  border-radius:50%;
  background:var(--paper);
  border:1px solid var(--line);
}
.summary-donut-center{
  position:relative;
  z-index:1;
  display:grid;
  justify-items:center;
  gap:3px;
  text-align:center;
}
.summary-donut-center strong{font-size:17px;letter-spacing:-.025em;font-variant-numeric:tabular-nums;}
.summary-donut-center span{font-size:10px;color:var(--muted);}
.summary-donut-legend{display:grid;gap:9px;min-width:0;}
.summary-legend-row{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:10.5px;}
.summary-legend-row>span{display:flex;align-items:center;gap:7px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
