.summary-account-row>strong{margin-left:auto;font-size:13px;font-variant-numeric:tabular-nums;white-space:nowrap;}
.summary-list-icon{
  width:32px;
  height:32px;
  flex:0 0 32px;
  display:grid;
  place-items:center;
  border-radius:7px;
  color:#fff;
  font-size:13px;
  font-weight:800;
  box-shadow:inset 0 0 0 1px #ffffff20;
}
.account-tone-1,.movement-tone-1,.upcoming-tone-1{background:#df147e;}
.account-tone-2,.movement-tone-2,.upcoming-tone-2{background:#397cff;}
.account-tone-3,.movement-tone-3,.upcoming-tone-3{background:#3abc78;}
