.data-inbox-description{display:grid;gap:1px;min-width:0;}
.data-inbox-description b,.data-inbox-description small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.data-inbox-description small{color:var(--muted);font-size:9px;}
.data-inbox-value{white-space:nowrap;font-size:11px;}
