.state-duplicate{color:#ff7777;background:rgba(255,119,119,.08);border-color:rgba(255,119,119,.25);}
.state-attention{color:#ffcf5d;background:rgba(255,207,93,.08);border-color:rgba(255,207,93,.22);}
.state-other{color:#9bd6ff;background:rgba(117,184,226,.08);border-color:rgba(117,184,226,.2);}
.data-inbox-suggestion{color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.data-inbox-actions{display:flex;align-items:center;justify-content:flex-end;gap:5px;}
.data-icon-button{min-height:27px!important;padding:4px 7px!important;font-size:9.5px!important;border-radius:6px!important;}
.data-row-menu{position:relative;}
