.data-quality-metric strong{font-size:16px;}
.data-quality-metric span:last-child{color:var(--muted);font-size:9.5px;line-height:1.25;}
.data-quality-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:8px;}
.data-quality-filters{display:flex;gap:2px;overflow:auto hidden;}
.data-quality-lastcheck{color:var(--muted);font-size:9.5px;white-space:nowrap;}
.data-quality-table{border:1px solid color-mix(in srgb,var(--line) 82%,transparent);border-radius:10px;overflow:hidden;}
.data-quality-th,.data-quality-tr{display:grid;grid-template-columns:150px minmax(260px,1fr) 90px 90px 80px;align-items:center;column-gap:10px;}
.data-quality-th{min-height:34px;padding:0 10px;background:color-mix(in srgb,var(--bg) 38%,transparent);border-bottom:1px solid var(--line);color:var(--muted);font-size:10px;}
.data-quality-tr{min-height:46px;padding:6px 10px;border-bottom:1px solid color-mix(in srgb,var(--line) 70%,transparent);font-size:10.5px;}
.data-quality-tr:last-child{border-bottom:0;}
.data-quality-tr:hover{background:color-mix(in srgb,var(--accent) 4%,transparent);}
.data-quality-kind{display:inline-flex;align-items:center;min-height:23px;padding:4px 7px;border-radius:6px;border:1px solid var(--line);white-space:nowrap;font-size:9px;}
