.kind-category,.kind-import{color:#f2b35e;background:rgba(242,179,94,.08);border-color:rgba(242,179,94,.22);}
.kind-beneficiary,.kind-account{color:#e0c75c;background:rgba(224,199,92,.08);border-color:rgba(224,199,92,.22);}
.kind-history,.kind-review,.kind-other{color:#b9a0ff;background:rgba(185,160,255,.08);border-color:rgba(185,160,255,.22);}
.data-quality-description{display:grid;gap:1px;min-width:0;}
.data-quality-description b{font-weight:600;}
.data-quality-description small{color:var(--muted);font-size:9px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.data-quality-count{text-align:center;font-weight:700;}
.data-impact{font-weight:650;}
.impact-alto{color:#ff737a}
.impact-médio{color:#f1bc59}
.impact-baixo{color:#43d49a}
.data-quality-tr button{min-height:27px!important;padding:4px 9px!important;font-size:9.5px!important;}
.data-quality-context{grid-column:2;margin-top:3px;padding:0 2px;color:var(--muted);font-size:10px;}
