  flex:0 0 auto;
  min-height:40px;
  padding:8px 11px;
  border:1px solid transparent;
  border-radius:10px;
  background:transparent;
  color:var(--muted);
  font:600 12px/1.2 'DM Sans',sans-serif;
  cursor:pointer;
  transition:background .15s ease,border-color .15s ease,color .15s ease;
}
.top-nav-link:hover{
  color:var(--ink);
  background:color-mix(in srgb,var(--accent) 7%,transparent);
}
.top-nav-link.active{
  color:var(--ink);
  background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 16%,transparent),color-mix(in srgb,var(--paper) 88%,transparent));
  border-color:color-mix(in srgb,var(--accent) 24%,var(--line));
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 4%,transparent);
}
.topbar-tools{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:9px;
  min-width:0;
}
.top-search-slot{
  width:min(290px,22vw);
  min-width:190px;
}
.top-search-slot .inline-global-search{
  position:relative;
  width:100%!important;
  min-width:0!important;
  max-width:none!important;
  margin:0!important;
}
.top-search-slot .inline-search-label{
  width:100%!important;
  min-height:38px!important;
  height:38px!important;
  display:flex!important;
  align-items:center!important;
  gap:7px!important;
  padding:0 10px!important;
  border:1px solid color-mix(in srgb,var(--accent) 12%,var(--line))!important;
  border-radius:9px!important;
  background:color-mix(in srgb,var(--paper) 87%,transparent)!important;
}
.top-search-slot .inline-search-label input{
  min-height:34px!important;
  height:34px!important;
  border:0!important;
  padding:0!important;
  background:transparent!important;
  box-shadow:none!important;
  font-size:12px!important;
}
.top-search-slot .inline-search-results{
  top:44px!important;
  right:0!important;
  left:auto!important;
  width:min(440px,80vw)!important;
  z-index:300!important;
}
.top-space-slot{
  flex:0 0 auto;
}
.top-space-slot .space-picker{
  display:flex!important;
  align-items:center!important;
  gap:7px!important;
  margin:0!important;
  padding:0!important;
}
.top-space-slot .space-picker label{
  position:absolute!important;
  width:1px!important;
  height:1px!important;
  overflow:hidden!important;
  clip:rect(0 0 0 0)!important;
  white-space:nowrap!important;
}
.top-space-slot .space-picker select{
  width:auto!important;
  min-width:116px!important;
  max-width:160px!important;
  height:38px!important;
  min-height:38px!important;
  margin:0!important;
  padding:0 30px 0 10px!important;
  border-radius:9px!important;
  border:1px solid color-mix(in srgb,var(--accent) 14%,var(--line))!important;
  background-color:color-mix(in srgb,var(--paper) 88%,transparent)!important;
  font-size:11px!important;
  font-weight:650!important;
}
main,
#mainContent{
  margin-left:0!important;
  max-width:none!important;
  width:100%!important;
  padding-left:clamp(22px,3vw,48px)!important;
  padding-right:clamp(22px,3vw,48px)!important;
}
#mainContent>header{
  margin-top:18px!important;
  margin-bottom:18px!important;
}
#mainContent>header h1{
  font-size:30px!important;
}
.workspace-bar{
  max-width:none!important;
}
.area-tabs{
  max-width:none!important;
}
body[data-current-view="dataHub"] #mainContent>header,
body[data-current-view="dataHub"] .workspace-bar{
  display:none!important;
}
body[data-current-view="dataHub"] #dataHub{
