}
body[data-current-view="dataHub"] .data-quality-ring{
  width:160px!important;
  height:160px!important;
}
body[data-current-view="dataHub"] .data-quality-metrics{
  gap:9px!important;
}
body[data-current-view="dataHub"] .data-quality-metric{
  min-height:67px!important;
}
body[data-current-view="dataHub"] .data-quality-table{
  border-color:color-mix(in srgb,var(--line) 86%,transparent)!important;
}
.settings-maintenance-panel{
  grid-column:1/-1;
  padding:18px!important;
  border-color:color-mix(in srgb,var(--accent) 14%,var(--line))!important;
  background:linear-gradient(145deg,color-mix(in srgb,var(--paper) 97%,transparent),color-mix(in srgb,var(--accent) 4%,var(--paper)))!important;
}
.settings-maintenance-heading{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:16px;
  margin-bottom:14px;
}
.settings-maintenance-heading h2{margin-bottom:4px!important;}
.settings-maintenance-heading p{margin:0!important;max-width:720px;}
.settings-maintenance-badge{
  display:inline-flex;
  align-items:center;
  min-height:27px;
  padding:5px 9px;
  border-radius:999px;
  border:1px solid color-mix(in srgb,var(--accent) 18%,var(--line));
  color:var(--muted);
  font-size:10px;
  font-weight:700;
}
.settings-maintenance-actions{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:10px;
}
.settings-maintenance-actions .maintenance-command{
  min-height:66px!important;
  display:grid!important;
  align-content:center!important;
  gap:4px!important;
  text-align:left!important;
  padding:11px 13px!important;
}
.settings-maintenance-actions .maintenance-command span{
  font-size:12px!important;
  font-weight:750!important;
  color:var(--ink)!important;
}
.settings-maintenance-actions .maintenance-command small{
  color:var(--muted)!important;
  font-size:10px!important;
  line-height:1.35!important;
}
.settings-maintenance-more{
  margin-top:12px;
  border-top:1px solid var(--line);
  padding-top:10px;
}
.settings-maintenance-more summary{
  cursor:pointer;
  color:var(--muted);
  font-size:11px;
  font-weight:700;
}
.settings-maintenance-more .secondary-actions{
  margin-top:10px;
  grid-template-columns:minmax(220px,1fr) repeat(2,minmax(0,1fr));
}
@media(max-width:1260px){
  .app-topbar{grid-template-columns:auto minmax(0,1fr);gap:10px 14px;}
}
@media(max-width:1260px){
  .topbar-tools{grid-column:1/-1;justify-content:space-between;}
}
@media(max-width:1260px){
  .top-search-slot{width:min(420px,55vw);}
}
@media(max-width:1260px){
  body{--topbar-height:112px;}
}
