}
@media(max-width:900px){
  .top-primary-nav{padding:0;mask-image:none;}
}
@media(max-width:900px){
  .top-nav-link{padding:7px 9px;font-size:11px;}
}
@media(max-width:900px){
  .topbar-tools{gap:7px;}
}
@media(max-width:900px){
  .top-search-slot{width:min(58vw,360px);min-width:140px;}
}
@media(max-width:900px){
  .top-space-slot .space-picker select{min-width:105px!important;max-width:130px!important;}
}
@media(max-width:900px){
  main,#mainContent{padding-left:16px!important;padding-right:16px!important;}
}
@media(max-width:900px){
  body[data-current-view="dataHub"] .data-inbox-filterbar{padding-left:14px!important;}
}
@media(max-width:900px){
  body[data-current-view="dataHub"] .data-inbox-layout,
  body[data-current-view="dataHub"] .data-quality-layout{grid-template-columns:1fr!important;}
}
@media(max-width:900px){
  .settings-maintenance-actions{grid-template-columns:1fr!important;}
}
@media(max-width:620px){
  .app-topbar{grid-template-columns:auto minmax(0,1fr);}
}
@media(max-width:620px){
  .topbar-tools{grid-column:1/-1;}
}
@media(max-width:620px){
  .top-search-slot{width:100%;flex:1 1 auto;}
}
@media(max-width:620px){
  .top-space-slot{flex:0 0 auto;}
}
@media(max-width:620px){
  .top-nav-link{min-height:36px;}
}
@media(max-width:620px){
  body{--topbar-height:108px;}
}
.top-brand img{
