body[data-current-view="weeklyHub"] .workspace-bar{
  display:none!important;
}
body[data-current-view="weeklyHub"] #mainContent{
  padding-top:18px!important;
}
body[data-current-view="weeklyHub"] #weeklyHub.review-page.active{
  display:block!important;
  max-width:none!important;
  width:100%!important;
  margin:0!important;
}
.review-hero{
  position:relative;
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:26px;
  margin:0 0 15px;
  padding:24px 26px;
  border:1px solid color-mix(in srgb,var(--line) 78%,transparent);
  border-radius:18px;
  overflow:hidden;
  background:
    radial-gradient(circle at 88% 8%,color-mix(in srgb,var(--accent) 13%,transparent),transparent 35%),
    linear-gradient(145deg,color-mix(in srgb,var(--paper) 98%,transparent),color-mix(in srgb,var(--accent) 4%,var(--paper)));
  box-shadow:0 12px 28px rgba(0,0,0,.055);
}
.review-hero:after{
  content:"";
  position:absolute;
  width:230px;
  height:230px;
  right:-105px;
  bottom:-145px;
  border:1px solid color-mix(in srgb,var(--accent) 25%,transparent);
  border-radius:50%;
  pointer-events:none;
}
.review-hero-copy{min-width:0;max-width:900px;position:relative;z-index:1;}
.review-hero h2{
  margin:5px 0 6px!important;
  font-size:clamp(30px,3vw,42px)!important;
  line-height:1.02!important;
  letter-spacing:-.045em!important;
}
.review-period{
  margin:0!important;
  color:var(--muted)!important;
  font-size:12.5px!important;
}
.review-hero-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:8px;
  flex-wrap:wrap;
  flex:0 0 auto;
  position:relative;
  z-index:1;
}
.review-week-story{
  display:flex;
  align-items:flex-start;
  gap:11px;
  max-width:820px;
  margin-top:18px;
  padding-top:16px;
  border-top:1px solid color-mix(in srgb,var(--line) 66%,transparent);
}
.review-story-dot{
  width:10px;
  height:10px;
  flex:0 0 10px;
  margin-top:5px;
  border-radius:50%;
  background:var(--accent);
  box-shadow:0 0 0 5px color-mix(in srgb,var(--accent) 12%,transparent);
}
.review-tone-watch .review-story-dot{background:#f2b84b;box-shadow:0 0 0 5px color-mix(in srgb,#f2b84b 12%,transparent);}
.review-tone-quiet .review-story-dot{background:var(--muted);box-shadow:0 0 0 5px color-mix(in srgb,var(--muted) 12%,transparent);}
.review-week-story b{display:block;margin-bottom:3px;font-size:14px;}
.review-week-story p{margin:0!important;color:var(--muted)!important;font-size:11.5px!important;line-height:1.5!important;}
.review-metrics-executive{
  grid-template-columns:repeat(4,minmax(0,1fr))!important;
  gap:11px!important;
  margin-bottom:11px!important;
}
.review-metrics-executive .review-metric{
  min-height:128px;
  padding:18px!important;
  border-radius:15px!important;
  border-color:color-mix(in srgb,var(--line) 74%,transparent)!important;
  background:linear-gradient(145deg,color-mix(in srgb,var(--paper) 98%,transparent),color-mix(in srgb,var(--accent) 3%,var(--paper)))!important;
  box-shadow:0 8px 20px rgba(0,0,0,.045);
}
.review-metrics-executive .review-metric strong{
  margin:8px 0 6px!important;
  font-size:28px!important;
  letter-spacing:-.035em!important;
}
.review-metrics-executive .review-metric small{font-size:10.5px!important;line-height:1.4!important;}
.review-main-grid{
  display:grid;
  grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);
  gap:11px;
  margin-bottom:11px;
}
.review-card{
  border-radius:16px!important;
  border-color:color-mix(in srgb,var(--line) 72%,transparent)!important;
  box-shadow:0 8px 20px rgba(0,0,0,.04)!important;
}
.review-card-heading{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:14px;
  margin-bottom:15px;
}
.review-card-heading h3{
  margin:3px 0 0!important;
  font-size:18px!important;
  letter-spacing:-.025em!important;
}
.review-card-heading p:not(.eyebrow){margin:4px 0 0!important;color:var(--muted)!important;font-size:11px!important;}
.review-delta-pill{
  display:inline-flex;
  align-items:center;
  min-height:30px;
  padding:5px 9px;
  border:1px solid var(--line);
  border-radius:999px;
  font-size:11px;
  font-weight:750;
  white-space:nowrap;
}
.review-comparison-bars{display:grid;gap:18px;}
.review-comparison-row{
  display:grid;
  grid-template-columns:minmax(130px,.85fr) minmax(150px,1.3fr) auto;
  gap:14px;
  align-items:center;
}
.review-comparison-row>div:first-child{display:grid;gap:3px;}
.review-comparison-row span{font-size:11px;font-weight:700;}
.review-comparison-row small{font-size:9.5px;color:var(--muted);}
.review-comparison-row strong{min-width:76px;text-align:right;font-size:13px;font-variant-numeric:tabular-nums;}
.review-bar-track{
  height:9px;
  overflow:hidden;
  border-radius:999px;
  background:color-mix(in srgb,var(--muted) 12%,transparent);
}
.review-bar-track i{
  display:block;
  width:var(--review-bar);
  height:100%;
  border-radius:inherit;
  background:color-mix(in srgb,var(--muted) 58%,var(--paper));
}
.review-comparison-row.current .review-bar-track i{
  background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 72%,#1b6f62),var(--accent));
}
.review-insights-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:9px;
}
.review-insights-grid article{
  min-width:0;
  min-height:105px;
  display:grid;
  align-content:start;
  gap:5px;
  padding:13px;
  border:1px solid color-mix(in srgb,var(--line) 72%,transparent);
  border-radius:12px;
  background:color-mix(in srgb,var(--canvas) 78%,transparent);
}
.review-insights-grid span{font-size:9px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);font-weight:750;}
.review-insights-grid b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;}
.review-insights-grid strong{margin-top:auto;font-size:14px;font-variant-numeric:tabular-nums;}
.review-movements-card,
.review-upcoming-card{
  margin-bottom:11px!important;
}
.review-day-group{
  border-top:1px solid color-mix(in srgb,var(--line) 68%,transparent);
}
.review-day-group:last-child{border-bottom:1px solid color-mix(in srgb,var(--line) 68%,transparent);}
.review-day-group>summary{
  min-height:50px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:16px;
  padding:9px 2px;
  cursor:pointer;
  list-style:none;
}
.review-day-group>summary::-webkit-details-marker{display:none;}
.review-day-group>summary>span{display:grid;gap:2px;}
.review-day-group>summary b{font-size:11.5px;}
