.review30-hero{
  display:grid;
  grid-template-columns:minmax(0,1.25fr) minmax(360px,.85fr) auto;
  align-items:center;
  gap:26px;
  margin:0 0 14px;
  padding:25px 27px;
  border:1px solid color-mix(in srgb,var(--line) 78%,transparent);
  border-radius:18px;
  background:
    radial-gradient(circle at 62% 42%,color-mix(in srgb,var(--accent) 8%,transparent),transparent 28%),
    linear-gradient(145deg,color-mix(in srgb,var(--paper) 98%,transparent),color-mix(in srgb,var(--accent) 4%,var(--paper)));
  box-shadow:0 13px 30px rgba(0,0,0,.055);
}
.review30-hero-title{min-width:0;}
.review30-hero-title h2{
  margin:5px 0 7px!important;
  font-size:clamp(31px,3.1vw,43px)!important;
  line-height:1.02!important;
  letter-spacing:-.045em!important;
}
.review30-hero-title>p:last-child{
  margin:0!important;
  color:var(--muted)!important;
  font-size:12.5px!important;
}
.review30-verdict{
  min-width:0;
  display:grid;
  grid-template-columns:52px minmax(0,1fr);
  align-items:center;
  gap:14px;
  padding-left:25px;
  border-left:1px solid color-mix(in srgb,var(--line) 72%,transparent);
}
.review30-verdict-icon{
  width:50px;
  height:50px;
  display:grid;
  place-items:center;
  border-radius:15px;
  background:color-mix(in srgb,var(--accent) 16%,var(--paper));
  color:var(--accent);
  font-size:22px;
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 18%,transparent);
}
.review30-verdict b{display:block;margin-bottom:4px;font-size:18px;letter-spacing:-.02em;}
.review30-verdict p{margin:0!important;color:var(--muted)!important;font-size:11.5px!important;line-height:1.45!important;}
.review30-tone-good .review30-verdict-icon{background:rgba(57,213,155,.14);color:#4ee1a9;}
.review30-tone-watch .review30-verdict-icon{background:rgba(255,103,120,.13);color:#ff7a89;}
.review30-tone-quiet .review30-verdict-icon{background:rgba(115,151,163,.13);color:var(--muted);}
.review30-hero-action{align-self:start;justify-self:end;}
.review30-hero-action button{white-space:nowrap!important;}
.review30-main-grid{
  display:grid;
  grid-template-columns:minmax(0,2.15fr) minmax(310px,.85fr);
  gap:14px;
  margin-bottom:14px;
}
.review30-bottom-grid{
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(0,1fr);
  gap:14px;
}
.review30-timeline-panel,.review30-conclusions,.review30-attention,.review30-next{
  margin:0!important;
  padding:20px 21px!important;
  border-radius:17px!important;
  border-color:color-mix(in srgb,var(--line) 76%,transparent)!important;
  background:linear-gradient(145deg,color-mix(in srgb,var(--paper) 98%,transparent),color-mix(in srgb,var(--bg) 15%,var(--paper)))!important;
  box-shadow:0 10px 24px rgba(0,0,0,.045)!important;
}
.review30-section-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:14px;
  margin-bottom:16px;
}
.review30-section-head .eyebrow{margin:0 0 4px!important;}
.review30-section-head h3{margin:0!important;font-size:16px!important;letter-spacing:-.018em!important;}
.review30-timeline{
  position:relative;
  display:grid;
  grid-template-columns:repeat(7,minmax(0,1fr));
  gap:8px;
  padding-top:6px;
}
.review30-timeline:before{
  content:"";
  position:absolute;
  top:24px;
  left:5%;
  right:5%;
  height:1px;
  background:color-mix(in srgb,var(--line) 88%,transparent);
}
.review30-day{
  min-width:0;
  position:relative;
  display:flex;
  flex-direction:column;
  align-items:stretch;
  text-align:left;
}
.review30-day-node{
  position:relative;
  z-index:2;
  height:38px;
  display:flex;
  justify-content:center;
  align-items:flex-start;
}
.review30-day-node span{
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  border-radius:50%;
  border:4px solid color-mix(in srgb,var(--paper) 92%,var(--bg));
  background:color-mix(in srgb,var(--muted) 22%,var(--paper));
  color:var(--muted);
  font-size:15px;
  font-weight:800;
  box-shadow:0 0 0 1px color-mix(in srgb,var(--line) 75%,transparent);
}
.review30-tone-good .review30-day-node span{background:rgba(57,213,155,.22);color:#5be6b3;}
.review30-tone-watch .review30-day-node span{background:rgba(255,103,120,.18);color:#ff7a89;}
.review30-day.is-current .review30-day-node span{box-shadow:0 0 0 2px color-mix(in srgb,var(--accent) 42%,transparent),0 0 18px color-mix(in srgb,var(--accent) 18%,transparent);}
.review30-day-date{
  margin:4px 0 7px!important;
  text-align:center;
  color:var(--muted)!important;
  font-size:9.5px!important;
  font-weight:700!important;
  text-transform:capitalize;
}
.review30-day-card{
  min-height:112px;
  padding:12px 12px 13px;
  border:1px solid color-mix(in srgb,var(--line) 68%,transparent);
  border-radius:12px;
  background:color-mix(in srgb,var(--paper) 87%,var(--bg));
}
.review30-day-card b{display:block;margin-bottom:6px;font-size:11px;}
.review30-day-card span{display:block;color:var(--muted);font-size:10px;line-height:1.45;overflow-wrap:anywhere;}
.review30-day.is-current .review30-day-card{border-color:color-mix(in srgb,var(--accent) 30%,var(--line));}
.review30-conclusions{display:flex;flex-direction:column;}
.review30-conclusion-row{
  display:grid;
  grid-template-columns:42px minmax(0,1fr);
  align-items:center;
  gap:11px;
  min-height:78px;
  padding:11px 12px;
  border:1px solid color-mix(in srgb,var(--line) 65%,transparent);
  border-radius:12px;
  background:color-mix(in srgb,var(--paper) 87%,var(--bg));
}
.review30-conclusion-row+.review30-conclusion-row{margin-top:8px;}
.review30-conclusion-row>span{
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  border-radius:50%;
  font-size:18px;
  font-weight:800;
}
.review30-conclusion-row.good>span{background:rgba(57,213,155,.16);color:#4ee1a9;}
.review30-conclusion-row.watch>span{background:rgba(255,103,120,.14);color:#ff7a89;}
.review30-conclusion-row.neutral>span{background:rgba(115,151,163,.13);color:var(--muted);}
.review30-conclusion-row b{display:block;margin-bottom:3px;font-size:11.5px;}
.review30-conclusion-row p{margin:0!important;color:var(--muted)!important;font-size:10px!important;line-height:1.42!important;}
.review30-attention-list{display:grid;gap:0;}
.review30-attention-row{
  width:100%;
  min-height:60px;
  display:grid;
  grid-template-columns:38px minmax(0,1fr) auto;
  align-items:center;
  gap:11px;
  padding:9px 5px!important;
  border:0!important;
  border-bottom:1px solid color-mix(in srgb,var(--line) 67%,transparent)!important;
  border-radius:0!important;
  background:transparent!important;
  box-shadow:none!important;
  color:var(--ink)!important;
  text-align:left!important;
}
.review30-attention-row:last-child{border-bottom:0!important;}
.review30-attention-row:hover{background:color-mix(in srgb,var(--accent) 5%,transparent)!important;}
.review30-attention-icon{
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:10px;
  background:rgba(255,177,69,.13);
  color:#f6bd59;
  font-weight:800;
}
.review30-attention-row>span:nth-child(2){display:grid;gap:2px;min-width:0;}
.review30-attention-row b{font-size:11.5px;white-space:normal;}
.review30-attention-row small{color:var(--muted);font-size:9.5px;white-space:normal;overflow-wrap:anywhere;}
.review30-attention-row i{font-style:normal;color:var(--muted);font-size:22px;}
.review30-empty-good{display:flex;align-items:center;gap:12px;padding:18px 4px;}
.review30-empty-good>span{width:36px;height:36px;display:grid;place-items:center;border-radius:50%;background:rgba(57,213,155,.15);color:#4ee1a9;font-weight:800;}
.review30-empty-good b,.review30-empty-good small{display:block;}
.review30-empty-good small{margin-top:3px;color:var(--muted);font-size:10px;}
.review30-next{display:flex;flex-direction:column;}
.review30-next-step-card{
  display:grid;
  grid-template-columns:54px minmax(0,1fr) auto;
  align-items:center;
  gap:15px;
  padding:17px 18px;
  border:1px solid color-mix(in srgb,var(--accent) 24%,var(--line));
  border-radius:14px;
  background:linear-gradient(120deg,color-mix(in srgb,var(--accent) 12%,var(--paper)),color-mix(in srgb,var(--paper) 96%,transparent));
}
.review30-next-icon{
  width:50px;
  height:50px;
  display:grid;
  place-items:center;
  border-radius:50%;
  background:rgba(57,213,155,.17);
  color:#55e1ad;
  font-size:20px;
  font-weight:800;
}
.review30-next-step-card b{display:block;margin-bottom:4px;font-size:13px;}
.review30-next-step-card p{margin:0!important;color:var(--muted)!important;font-size:10.5px!important;line-height:1.45!important;}
.review30-next-step-card button{white-space:nowrap!important;}
.review30-footnote{margin:14px 2px 0!important;color:var(--muted)!important;font-size:9.5px!important;line-height:1.45!important;}
@media(max-width:1250px){
  .review30-hero{grid-template-columns:minmax(0,1fr) minmax(310px,.8fr);}
}
@media(max-width:1250px){
  .review30-hero-action{grid-column:1/-1;justify-self:end;margin-top:-8px;}
}
@media(max-width:1250px){
  .review30-main-grid{grid-template-columns:1fr;}
}
@media(max-width:1250px){
  .review30-conclusions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;}
}
@media(max-width:1250px){
  .review30-conclusions .review30-section-head{grid-column:1/-1;}
}
@media(max-width:1250px){
  .review30-conclusion-row+.review30-conclusion-row{margin-top:0;}
}
@media(max-width:900px){
  .review30-hero{grid-template-columns:1fr;gap:18px;padding:21px;}
}
@media(max-width:900px){
  .review30-verdict{border-left:0;border-top:1px solid color-mix(in srgb,var(--line) 72%,transparent);padding:17px 0 0;}
}
@media(max-width:900px){
  .review30-hero-action{grid-column:auto;justify-self:start;margin-top:0;}
}
@media(max-width:900px){
  .review30-timeline{grid-template-columns:repeat(2,minmax(0,1fr));}
}
@media(max-width:900px){
  .review30-timeline:before{display:none;}
}
@media(max-width:900px){
  .review30-day-node{height:36px;justify-content:flex-start;}
}
@media(max-width:900px){
  .review30-day-date{text-align:left;}
}
@media(max-width:900px){
  .review30-day-card{min-height:88px;}
}
@media(max-width:900px){
  .review30-conclusions{grid-template-columns:1fr;}
}
@media(max-width:900px){
  .review30-conclusions .review30-section-head{grid-column:auto;}
}
@media(max-width:900px){
  .review30-bottom-grid{grid-template-columns:1fr;}
}
@media(max-width:560px){
  .review30-timeline{grid-template-columns:1fr;}
}
@media(max-width:560px){
  .review30-next-step-card{grid-template-columns:44px minmax(0,1fr);}
}
@media(max-width:560px){
  .review30-next-step-card button{grid-column:1/-1;justify-self:start;}
}
