:is(#plansHub, #goals, #budgets, #planningPlus, #decisionsHub) {
  --plan-border: var(--gui-border, var(--line));
  --plan-surface: var(--gui-surface, var(--paper));
  --plan-soft: var(--gui-soft, var(--canvas));
  --plan-text: var(--gui-text, var(--ink));
  --plan-muted: var(--gui-muted, var(--muted));
  --plan-accent: var(--gui-accent, var(--blue));
}
:is(#plansHub, #goals, #budgets, #planningPlus) > .section-head {
  position: relative;
  min-width: 0;
  padding: 23px 26px !important;
  margin: 0 0 20px !important;
  border: 1px solid var(--plan-border);
  border-radius: 17px;
  background: linear-gradient(105deg,
    color-mix(in srgb, var(--plan-accent) 9%, var(--plan-surface)) 0%,
    var(--plan-surface) 72%);
  overflow: hidden;
}
:is(#plansHub, #goals, #budgets, #planningPlus) > .section-head::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--plan-accent);
}
:is(#plansHub, #goals, #budgets, #planningPlus) > .section-head h2 {
  display: block !important;
  margin: 0 0 4px !important;
  color: var(--plan-text);
  font-size: clamp(22px, 2vw, 28px);
  font-weight: 750;
  line-height: 1.2;
}
:is(#plansHub, #goals, #budgets, #planningPlus) > .section-head p {
  max-width: 65ch;
  margin: 0;
  color: var(--plan-muted);
  font-size: 13px;
  line-height: 1.55;
}
:is(#goals, #budgets) > .section-head .primary {
  flex: 0 0 auto;
  min-height: 42px;
  white-space: nowrap;
