.welcome-dialog{width:min(1010px,calc(100vw - 32px));max-width:none;max-height:min(760px,calc(100vh - 32px));padding:0;border:1px solid #d6e5e1;border-radius:24px;background:#fff;color:#20343a;box-shadow:0 32px 90px #102b2d55;overflow:auto}
.welcome-dialog::backdrop{background:#082427a8;backdrop-filter:blur(4px)}
.welcome-shell{display:grid;grid-template-columns:minmax(310px,.88fr) minmax(0,1.12fr);min-height:560px}
.welcome-hero{position:relative;display:flex;flex-direction:column;align-items:flex-start;padding:38px 42px;overflow:hidden;background:linear-gradient(145deg,#113d3c 0%,#185a50 54%,#18735c 100%);color:#f7fff9;isolation:isolate}
.welcome-hero::before,.welcome-hero::after{content:"";position:absolute;z-index:-1;border:1px solid #d5f6d12e;border-radius:50%}
.welcome-hero::before{width:390px;height:390px;right:-235px;top:86px;box-shadow:0 0 0 58px #d5f6d10b,0 0 0 116px #d5f6d108}
.welcome-hero::after{width:220px;height:220px;left:-125px;bottom:-105px;box-shadow:0 0 0 60px #d5f6d10b}
.welcome-brand{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:800;letter-spacing:.01em}
.welcome-brand img{width:33px;height:33px;object-fit:contain}
.welcome-kicker{margin:auto 0 14px;font-size:11px;font-weight:800;letter-spacing:.18em;color:#a5e3ca}
.welcome-hero h2{max-width:390px;margin:0 0 18px;font-size:clamp(35px,4vw,52px);line-height:1.04;letter-spacing:-.045em;color:#fff}
.welcome-hero>p:not(.welcome-kicker){max-width:370px;margin:0;color:#d7f2e8;font-size:15px;line-height:1.65}
.welcome-hero-note{display:flex;align-items:center;gap:9px;margin-top:auto;padding-top:40px;color:#e1f7ed;font-size:12px;line-height:1.45}
.welcome-hero-note span{display:grid;place-items:center;width:22px;height:22px;flex:0 0 22px;border-radius:50%;background:#d5f6d126;color:#b8f0d6;font-weight:800}
.welcome-content{position:relative;display:flex;flex-direction:column;padding:55px 52px 34px}
.welcome-close{position:absolute;top:20px;right:22px;width:34px;height:34px;padding:0;border:1px solid #dce8e4;border-radius:10px;background:#fff;color:#436063;font-size:25px;line-height:1;cursor:pointer}
.welcome-step{margin:0 0 11px;color:#16715e;font-size:11px;font-weight:800;letter-spacing:.18em}
.welcome-content h3{margin:0 0 8px;color:#21363a;font-size:28px;letter-spacing:-.035em}
.welcome-intro{max-width:440px;margin:0 0 24px;color:#667a7d;font-size:14px;line-height:1.55}
.welcome-spaces{display:grid;gap:10px;max-height:245px;overflow:auto;padding:2px 3px 2px 2px}
.welcome-space{display:flex;align-items:center;gap:13px;min-height:68px;padding:11px 15px;border:1px solid #dce9e5;border-radius:13px;background:#fbfdfc;cursor:pointer;transition:border-color .16s,background .16s,transform .16s}
.welcome-space:hover{border-color:#9dcbbd;transform:translateY(-1px)}
.welcome-space:has(input:checked){border-color:#3b9b77;background:#eff9f4;box-shadow:inset 0 0 0 1px #3b9b7744}
.welcome-space input{position:absolute;width:1px;height:1px;opacity:0}
.welcome-space:has(input:focus-visible){outline:3px solid #80c6a7;outline-offset:2px}
.welcome-avatar{display:grid;place-items:center;width:41px;height:41px;flex:0 0 41px;border-radius:12px;background:#e2f1eb;color:#13654f;font-size:18px;font-weight:800}
.welcome-space-copy{display:grid;gap:3px;min-width:0}
.welcome-space-copy strong{overflow:hidden;color:#1e3d3c;font-size:14px;text-overflow:ellipsis;white-space:nowrap}
.welcome-space-copy small{color:#708582;font-size:11px}
.welcome-selected{display:grid;place-items:center;width:22px;height:22px;margin-left:auto;border:1px solid #bdcfca;border-radius:50%;color:transparent;font-size:12px}
.welcome-space:has(input:checked) .welcome-selected{border-color:#14805e;background:#14805e;color:#fff}
.welcome-actions{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:10px;margin-top:23px}
.welcome-actions button{min-height:45px;border-radius:10px;font-size:13px;font-weight:750}
.welcome-actions .primary{background:#116f57;color:#fff}
.welcome-actions .primary:hover{background:#0c5b48}
.welcome-actions .secondary{background:#fff;color:#285c52;border:1px solid #cbded8}
.welcome-configure{align-self:flex-start;margin-top:15px;padding:3px 0;border:0;background:transparent;color:#19755d;font-size:12px;font-weight:750;text-decoration:underline;text-underline-offset:3px;cursor:pointer}
.welcome-preference{display:flex!important;align-items:center!important;justify-content:flex-start!important;gap:8px!important;margin-top:auto;padding-top:24px;color:#6c7f7c;font-size:12px}
.welcome-preference input{width:16px!important;height:16px!important;min-width:16px!important;min-height:16px!important;flex:0 0 16px!important;margin:0!important;accent-color:#157c60}
.movement-category-icon{display:inline-flex;align-items:center;justify-content:center;width:15px;height:15px;flex:0 0 15px}
.movement-category-icon svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
body[data-current-view="transactions"] .movement-table-row>.movement-description-cell{padding-left:38px!important}
.movement-description-avatar{position:absolute;left:3px;top:50%;display:grid;place-items:center;width:28px;height:28px;border-radius:9px;color:#fff;transform:translateY(-50%);font-style:normal}
.movement-description-avatar svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
#transactionsTable .movement-table-row:focus{outline:2px solid #27a778;outline-offset:-2px}
body[data-theme="dark"] .welcome-launcher{border-color:#476461;background:#1a3538;color:#d8f4e8}
body[data-theme="dark"] .welcome-dialog{border-color:#496762;background:#1b3034;color:#edf8f4}
body[data-theme="dark"] .welcome-content h3,body[data-theme="dark"] .welcome-space-copy strong{color:#e9f8f1}
body[data-theme="dark"] .welcome-intro,body[data-theme="dark"] .welcome-preference{color:#b5cbc5}
body[data-theme="dark"] .welcome-space{border-color:#48645e;background:#263f40}
body[data-theme="dark"] .welcome-space:has(input:checked){border-color:#58ad84;background:#285345}
body[data-theme="dark"] .welcome-avatar{background:#345d51;color:#d4f7df}
body[data-theme="dark"] .welcome-space-copy small{color:#b3c9c0}
body[data-theme="dark"] .welcome-close,body[data-theme="dark"] .welcome-actions .secondary{border-color:#52716a;background:#284345;color:#e8f9ef}
@media(max-width:700px){
  .welcome-dialog{width:calc(100vw - 18px);max-height:calc(100vh - 18px);border-radius:18px}
}
