  .welcome-close{top:13px;right:15px}
}
@media(max-width:700px){
  .welcome-content h3{font-size:24px}
}
@media(max-width:700px){
  .welcome-intro{margin-bottom:16px}
}
@media(max-width:700px){
  .welcome-spaces{max-height:190px}
}
@media(max-width:700px){
  .welcome-actions{grid-template-columns:1fr}
}
@media(max-width:700px){
  .welcome-preference{padding-top:18px}
}
@media(max-width:360px){
  .topbar-tools{flex-wrap:wrap;justify-content:flex-end}
}
@media(max-width:360px){
  .top-search-slot{flex:1 0 100%;min-width:0;width:100%}
}
@media(max-width:360px){
