#reportDesk .r-hint{margin:4px 0 0;font-size:12px;color:var(--muted)}
#reportDesk .r-empty-panel{text-align:center;padding:40px 20px}
#reportDesk .r-cat-summary{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:24px;align-items:center}
#reportDesk .r-cat-chart{display:flex;align-items:center;gap:26px;min-width:0}
#reportDesk .r-donut{position:relative;flex:0 0 190px;width:190px;height:190px;border-radius:50%;display:grid;place-items:center}
#reportDesk .r-donut>div{width:118px;height:118px;border-radius:50%;background:var(--paper);display:grid;place-content:center;text-align:center;gap:2px;box-shadow:inset 0 0 0 1px var(--line)}
#reportDesk .r-donut small{font-size:11px;color:var(--muted)}
#reportDesk .r-donut b{font-size:15px}
#reportDesk .r-legend-list{list-style:none;margin:0;padding:0;display:grid;gap:7px;min-width:0;flex:1}
#reportDesk .r-legend-list li{display:grid;grid-template-columns:10px minmax(0,1fr) auto;gap:9px;align-items:center;font-size:13px}
#reportDesk .r-legend-list i{width:10px;height:10px;border-radius:3px}
#reportDesk .r-legend-list span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#reportDesk .r-legend-list b{font-size:12px;color:var(--muted);font-weight:600}
#reportDesk .r-highlights{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
#reportDesk .r-highlights article{background:var(--surface-soft);border-radius:12px;padding:14px;display:grid;gap:4px;min-width:0}
#reportDesk .r-highlights span{font-size:11.5px;color:var(--muted)}
#reportDesk .r-highlights article strong{font-size:17px!important;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#reportDesk .r-highlights small{font-size:11.5px;color:var(--muted)}
#reportDesk .r-tree-actions{display:flex;gap:8px}
#reportDesk .r-tree-actions button{min-height:32px;padding:5px 12px;font-size:12.5px}
#reportDesk .r-tree-head,#reportDesk .r-tree summary,#reportDesk .r-tree-child{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(120px,1fr) 100px 90px 120px;gap:14px;align-items:center}
#reportDesk .r-tree-head{padding:8px 14px;font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);border-bottom:1px solid var(--line)}
#reportDesk .r-tree-head span:nth-child(n+3){text-align:right}
#reportDesk .r-tree details{border-bottom:1px solid var(--line)}
#reportDesk .r-tree summary{list-style:none;cursor:pointer;padding:12px 14px;border-radius:10px}
#reportDesk .r-tree summary::-webkit-details-marker{display:none}
#reportDesk .r-tree summary:hover{background:var(--surface-soft)}
#reportDesk .r-tree details[open]>summary{background:var(--surface-soft)}
#reportDesk .r-tree-name{display:flex;align-items:center;gap:9px;min-width:0;font-weight:600;font-size:14px}
#reportDesk .r-tree-name>i{flex:0 0 10px;height:10px;border-radius:3px}
#reportDesk .r-tree-name small{font-weight:400;font-size:11.5px;color:var(--muted);white-space:nowrap}
#reportDesk .r-tree summary .r-tree-name::before{content:'›';display:inline-block;width:10px;color:var(--muted);transition:transform .15s;font-size:16px;line-height:1}
#reportDesk .r-tree details[open] summary .r-tree-name::before{transform:rotate(90deg)}
#reportDesk .r-tree-share{display:grid;grid-template-columns:minmax(0,1fr) 46px;gap:8px;align-items:center}
#reportDesk .r-tree-share i{height:7px;border-radius:99px;background:var(--line);overflow:hidden;display:block}
#reportDesk .r-tree-share em{display:block;height:100%;border-radius:99px}
#reportDesk .r-tree-share small{font-size:11.5px;color:var(--muted);text-align:right;white-space:nowrap}
#reportDesk .r-tree-avg{text-align:right;font-size:13px;color:var(--muted)}
#reportDesk .r-tree summary>span:nth-child(4),#reportDesk .r-tree-child>span:nth-child(4){text-align:right}
#reportDesk .r-tree summary>button,#reportDesk .r-tree-child>button{justify-self:end;font-weight:700;font-size:14px}
#reportDesk .r-tree-children{padding:4px 0 10px 33px}
#reportDesk .r-tree-child{padding:7px 14px 7px 0;border-top:1px dashed var(--line)}
#reportDesk .r-tree-child:first-child{border-top:0}
#reportDesk .r-tree-child .r-tree-name{font-weight:500;font-size:13px}
#reportDesk .r-tree-child .r-tree-share{grid-template-columns:minmax(0,1fr) 100px}
#reportDesk .r-tree-child>button{font-weight:600;font-size:13px}
#reportDesk .r-delta{display:inline-flex;align-items:center;justify-content:center;gap:2px;padding:2px 7px;border-radius:99px;font-size:11px;font-weight:700;white-space:nowrap}
#reportDesk .r-delta.is-good{background:color-mix(in srgb,var(--green) 14%,transparent);color:var(--green)}
#reportDesk .r-delta.is-bad{background:color-mix(in srgb,var(--red) 14%,transparent);color:var(--red)}
#reportDesk .r-delta.is-flat,#reportDesk .r-delta.is-new{background:var(--surface-soft);color:var(--muted)}
#reportDesk .r-trend-totals{display:grid;grid-template-columns:repeat(auto-fit,minmax(34px,1fr));gap:6px;height:92px;margin:6px 0 16px}
#reportDesk .r-trend-totals button{display:grid;grid-template-rows:1fr auto;gap:4px;background:transparent;border:0;padding:0;min-height:0;cursor:pointer}
#reportDesk .r-trend-totals i{display:flex;align-items:flex-end;background:var(--surface-soft);border-radius:6px;overflow:hidden}
#reportDesk .r-trend-totals em{display:block;width:100%;background:var(--blue);border-radius:6px 6px 0 0;opacity:.85}
#reportDesk .r-trend-totals button:hover em{opacity:1}
#reportDesk .r-trend-totals small{font-size:11px;color:var(--muted);text-align:center}
#reportDesk .r-heat-table{font-size:12px}
#reportDesk .r-heat-table th,#reportDesk .r-heat-table td{padding:4px 3px;text-align:center;white-space:nowrap}
#reportDesk .r-heat-table th[scope=row],#reportDesk .r-heat-table tfoot th{text-align:left;padding-right:10px;font-weight:600;max-width:190px;overflow:hidden;text-overflow:ellipsis}
#reportDesk .r-heat-table td.amount{text-align:right;padding-left:10px}
#reportDesk .r-heat-table tfoot td,#reportDesk .r-heat-table tfoot th{border-top:2px solid var(--line);font-weight:700;padding-top:8px}
#reportDesk .r-heat{width:100%;min-width:50px;min-height:30px;padding:4px 6px;border:0;border-radius:7px;font-size:11.5px;font-weight:600;background:color-mix(in srgb,var(--blue) calc(var(--heat)*100%),transparent);color:var(--ink);cursor:pointer}
#reportDesk .r-heat:hover{outline:2px solid var(--blue);outline-offset:-2px}
#reportDesk .r-heat-empty{color:var(--line)}
#reportDesk .r-compare-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
#reportDesk .r-compare-card{display:grid;gap:6px;padding:18px}
#reportDesk .r-compare-card span{font-size:12px;color:var(--muted)}
#reportDesk .panel.r-compare-card strong{font-size:21px!important;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#reportDesk .r-compare-card small{font-size:12px;color:var(--muted);display:flex;gap:6px;align-items:center;flex-wrap:wrap}
#reportDesk .r-compare-movers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
#reportDesk .r-mover{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 12px;width:100%;text-align:left;padding:10px 12px;margin-top:6px;border:1px solid var(--line);border-left-width:4px;border-radius:10px;background:var(--paper);color:var(--ink);cursor:pointer;min-height:0}
#reportDesk .r-mover.is-bad{border-left-color:var(--red)}
#reportDesk .r-mover.is-good{border-left-color:var(--green)}
#reportDesk .r-mover span{font-weight:600}
#reportDesk .r-mover small{grid-column:1/-1;font-size:11.5px;color:var(--muted)}
#reportDesk .r-legend .is-good{color:var(--green)}
#reportDesk .r-legend .is-bad{color:var(--red)}
#reportDesk .r-compare-head,#reportDesk .r-compare-row{display:grid;grid-template-columns:minmax(0,1.2fr) 110px 110px minmax(160px,1.4fr);gap:14px;align-items:center;padding:9px 6px}
#reportDesk .r-compare-head{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);border-bottom:1px solid var(--line)}
#reportDesk .r-compare-head span:nth-child(2),#reportDesk .r-compare-head span:nth-child(3){text-align:right}
#reportDesk .r-compare-row{border-bottom:1px solid var(--line);font-size:13px}
#reportDesk .r-compare-row>span:first-child{font-weight:600}
#reportDesk .r-diverge{position:relative;display:grid;grid-template-columns:1fr;align-items:center;height:26px;background:linear-gradient(var(--line),var(--line)) center/1px 100% no-repeat}
#reportDesk .r-diverge i{position:absolute;top:6px;height:14px;width:var(--w);border-radius:4px}
#reportDesk .r-diverge i.is-bad{left:50%;background:color-mix(in srgb,var(--red) 55%,transparent)}
#reportDesk .r-diverge i.is-good{right:50%;background:color-mix(in srgb,var(--green) 55%,transparent)}
#reportDesk .r-diverge b{position:relative;justify-self:end;font-size:12px;background:var(--paper);padding:0 4px;border-radius:4px}
#reportDesk .r-merchant-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:18px;align-items:start}
#reportDesk .r-merchant-panel input[type=search]{max-width:280px;min-height:36px;font-size:13px}
#reportDesk .r-merchant-head,#reportDesk .r-merchant{display:grid;grid-template-columns:30px minmax(0,1fr) 48px 90px 100px;gap:12px;align-items:center}
#reportDesk .r-merchant-head{padding:8px 10px;font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);border-bottom:1px solid var(--line)}
#reportDesk .r-merchant-head span:nth-child(n+3){text-align:right}
#reportDesk .r-merchant{width:100%;padding:10px;border:0;border-bottom:1px solid var(--line);border-radius:0;background:transparent;color:var(--ink);text-align:left;cursor:pointer;min-height:0}
#reportDesk .r-merchant:hover{background:var(--surface-soft)}
#reportDesk .r-merchant>span:nth-child(n+3),#reportDesk .r-merchant>b{text-align:right;font-size:13px}
#reportDesk .r-rank{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--surface-soft);font-size:11px;font-weight:700;color:var(--muted)}
#reportDesk .r-merchant-name{display:grid;gap:3px;min-width:0}
#reportDesk .r-merchant-name b{font-size:13.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#reportDesk .r-merchant-name small{font-size:11.5px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#reportDesk .r-merchant-name i{height:4px;border-radius:99px;background:var(--line);overflow:hidden;display:block}
#reportDesk .r-merchant-name em{display:block;height:100%;background:var(--blue);border-radius:99px}
#reportDesk .r-big{display:flex;justify-content:space-between;gap:12px;align-items:center;width:100%;padding:10px 4px;border:0;border-bottom:1px solid var(--line);border-radius:0;background:transparent;color:var(--ink);text-align:left;cursor:pointer;min-height:0}
#reportDesk .r-big:hover{background:var(--surface-soft)}
#reportDesk .r-big span{display:grid;gap:2px;min-width:0}
#reportDesk .r-big span b{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#reportDesk .r-big small{font-size:11.5px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#reportDesk .r-income-row{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(120px,1fr) 160px 110px;gap:16px;align-items:center;padding:12px 4px;border-bottom:1px solid var(--line)}
#reportDesk .r-income-row>button{justify-self:start;font-weight:600;text-align:left}
#reportDesk .r-income-row>b{text-align:right}
#reportDesk .r-spark{display:flex;align-items:flex-end;gap:2px;height:28px}
#reportDesk .r-spark em{flex:1;border-radius:2px 2px 0 0;opacity:.8;min-width:3px}
@media (max-width:1100px){#reportDesk .r-cat-summary,#reportDesk .r-merchant-grid{grid-template-columns:1fr}#reportDesk .r-tree-head,#reportDesk .r-tree summary,#reportDesk .r-tree-child{grid-template-columns:minmax(0,1.4fr) minmax(90px,1fr) 80px 110px}#reportDesk .r-tree-head span:nth-child(3),#reportDesk .r-tree-avg,#reportDesk .r-tree-child>span:nth-child(3){display:none}}
@media (max-width:760px){#reportDesk .r-cat-chart{flex-direction:column}#reportDesk .r-compare-cards,#reportDesk .r-compare-movers,#reportDesk .r-highlights{grid-template-columns:1fr}#reportDesk .r-compare-head,#reportDesk .r-compare-row{grid-template-columns:minmax(0,1fr) 90px 90px}#reportDesk .r-compare-head span:nth-child(4),#reportDesk .r-diverge{grid-column:1/-1}#reportDesk .r-income-row{grid-template-columns:minmax(0,1fr) auto}#reportDesk .r-income-row .r-tree-share,#reportDesk .r-spark{grid-column:1/-1}}
#reportDesk .r-warning{margin:0;padding:12px 14px;border-radius:12px;font-size:13px;background:color-mix(in srgb,var(--orange) 14%,var(--paper));border:1px solid color-mix(in srgb,var(--orange) 40%,transparent);color:var(--ink)}
#plansHub #plansBoard{display:grid;gap:22px;min-width:0;color:var(--ink)}
#plansHub #plansBoard .pl-head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;flex-wrap:wrap;margin:4px 0 0}
#plansHub #plansBoard .pl-head h2{font-size:28px;margin:0 0 6px}
#plansHub #plansBoard .pl-head p{margin:0;color:var(--muted);font-size:13.5px}
#plansHub #plansBoard .pl-head .u-actions{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap}
#plansHub #plansBoard .pl-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
#plansHub #plansBoard .pl-tile{display:flex;gap:14px;align-items:flex-start;padding:18px;border-radius:16px;background:var(--paper);border:1px solid var(--line);min-width:0}
#plansHub #plansBoard .pl-tile>svg{flex:0 0 38px;width:38px;height:38px;padding:9px;border-radius:12px;background:color-mix(in srgb,var(--blue) 12%,transparent);color:var(--blue)}
#plansHub #plansBoard .pl-tile.is-warn>svg{background:color-mix(in srgb,var(--orange) 16%,transparent);color:var(--orange)}
#plansHub #plansBoard .pl-tile div{display:grid;gap:3px;min-width:0}
#plansHub #plansBoard .pl-tile span{font-size:12px;color:var(--muted)}
#plansHub #plansBoard .pl-tile strong{font-size:22px!important;font-weight:700!important;line-height:1.2}
#plansHub #plansBoard .pl-tile small{font-size:12px;color:var(--muted)}
#plansHub #plansBoard .pl-main{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:20px;align-items:start}
#plansHub #plansBoard .pl-main.is-empty{grid-template-columns:minmax(0,1fr)}
#plansHub #plansBoard .pl-plans,#plansHub #plansBoard .pl-tools-section,#plansHub #plansBoard .pl-inspector,#plansHub #plansBoard .pl-context-card,#plansHub #plansBoard .pl-comparison:not(:empty){background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:22px;min-width:0}
#plansHub #plansBoard .pl-section-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;margin-bottom:18px}
#plansHub #plansBoard .pl-section-head h3{margin:0 0 10px;font-size:17px}
#plansHub #plansBoard .pl-section-head p{margin:-4px 0 0;color:var(--muted);font-size:13px}
#plansHub #plansBoard .pl-section-actions{display:flex;gap:8px;align-items:center}
#plansHub #plansBoard .pl-chips{display:flex;gap:6px;flex-wrap:wrap}
#plansHub #plansBoard .pl-chips button{display:inline-flex;align-items:center;gap:7px;min-height:34px;padding:6px 14px;border-radius:99px;border:1px solid var(--line);background:transparent;color:var(--muted);font-size:13px;font-weight:600}
#plansHub #plansBoard .pl-chips button small{display:inline-grid;place-items:center;min-width:20px;height:20px;padding:0 6px;border-radius:99px;background:var(--surface-soft);font-size:11px}
#plansHub #plansBoard .pl-chips button.active{background:var(--blue);border-color:var(--blue);color:#fff}
#plansHub #plansBoard .pl-chips button.active small{background:rgba(255,255,255,.22);color:#fff}
#plansHub #plansBoard .pl-manage{position:relative}
#plansHub #plansBoard .pl-manage>summary{list-style:none;cursor:pointer;display:inline-flex;align-items:center;min-height:36px;padding:7px 14px;border-radius:10px;border:1px solid var(--line);font-size:13px;font-weight:600}
#plansHub #plansBoard .pl-manage>summary::-webkit-details-marker{display:none}
#plansHub #plansBoard .pl-manage>summary::after{content:'▾';margin-left:8px;font-size:11px;color:var(--muted)}
#plansHub #plansBoard .pl-manage>div{position:absolute;right:0;top:calc(100% + 6px);z-index:30;display:grid;gap:4px;min-width:200px;padding:8px;border-radius:12px;background:var(--paper);border:1px solid var(--line);box-shadow:0 14px 34px rgba(15,30,40,.16)}
#plansHub #plansBoard .pl-manage>div button{justify-content:flex-start;text-align:left;border:0;background:transparent;min-height:36px}
#plansHub #plansBoard .pl-manage>div button:hover{background:var(--surface-soft)}
#plansHub #plansBoard .pl-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px}
#plansHub #plansBoard .pl-card{--kind:var(--blue);position:relative;display:grid;gap:6px;padding:16px 16px 14px;border-radius:14px;border:1px solid var(--line);background:var(--paper);cursor:pointer;transition:border-color .15s,box-shadow .15s,transform .15s;overflow:hidden}
#plansHub #plansBoard .pl-card::before{content:'';position:absolute;inset:0 auto 0 0;width:4px;background:var(--kind)}
#plansHub #plansBoard .pl-card:hover{border-color:color-mix(in srgb,var(--kind) 45%,var(--line));box-shadow:0 8px 22px rgba(15,30,40,.08);transform:translateY(-1px)}
#plansHub #plansBoard .pl-card.is-selected{border-color:var(--kind);box-shadow:0 0 0 3px color-mix(in srgb,var(--kind) 18%,transparent)}
#plansHub #plansBoard .kind-reserve{--kind:#c98a2e}
#plansHub #plansBoard .kind-budget{--kind:#5b7fd6}
#plansHub #plansBoard .pl-card-top,#plansHub #plansBoard .pl-inspector-top{display:flex;justify-content:space-between;align-items:center;gap:8px}
#plansHub #plansBoard .pl-kind{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--kind,var(--blue))}
#plansHub #plansBoard .pl-status{font-size:11px;font-weight:700;padding:3px 9px;border-radius:99px;background:color-mix(in srgb,var(--green) 13%,transparent);color:var(--green);white-space:nowrap}
#plansHub #plansBoard .pl-status.is-warn{background:color-mix(in srgb,var(--orange) 16%,transparent);color:var(--orange)}
#plansHub #plansBoard .pl-status.is-over{background:color-mix(in srgb,var(--red) 14%,transparent);color:var(--red)}
#plansHub #plansBoard .pl-status.is-done{background:var(--blue);color:#fff}
#plansHub #plansBoard .pl-card .u-record-button{all:unset;cursor:pointer;font-size:16px;font-weight:700;line-height:1.3;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#plansHub #plansBoard .pl-card .u-record-button:focus-visible{outline:2px solid var(--blue);outline-offset:3px;border-radius:4px}
#plansHub #plansBoard .pl-meta{font-size:12px;color:var(--muted);margin:0}
#plansHub #plansBoard .pl-amounts{display:flex;align-items:baseline;gap:6px;margin-top:6px}
#plansHub #plansBoard .pl-amounts b{font-size:20px!important;font-weight:700!important}
#plansHub #plansBoard .pl-amounts span{font-size:12.5px;color:var(--muted)}
#plansHub #plansBoard .pl-bar{height:8px;border-radius:99px;background:var(--surface-soft);overflow:hidden}
#plansHub #plansBoard .pl-bar i{display:block;height:100%;border-radius:99px;background:var(--kind)}
#plansHub #plansBoard .pl-bar.is-warn i{background:var(--orange)}
#plansHub #plansBoard .pl-bar.is-over i{background:var(--red)}
#plansHub #plansBoard .pl-foot{display:flex;justify-content:space-between;font-size:12px;color:var(--muted)}
#plansHub #plansBoard .pl-foot span:first-child{font-weight:700;color:var(--ink)}
#plansHub #plansBoard .pl-empty-filter{margin:0;padding:30px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:14px}
#plansHub #plansBoard .pl-starters>p{margin:0 0 14px;color:var(--muted);font-size:14px}
#plansHub #plansBoard .pl-starters>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
